    /******************************************************************
     * 全局AI调用管理（非敏感配置 + 七业务脚本密钥适配器）
     *
     * 管理器继续保持@grant none，避免破坏document-start阶段对HIS原生
     * XHR/fetch的拦截。API Key不写入管理器localStorage：各业务脚本
     * 通过闭包适配器把密钥保存在自己的Tampermonkey GM/既有安全存储中。
     * 管理器这里只保存服务商、直出/推理模式和模型名等非敏感策略。
     ******************************************************************/
    const GLOBAL_AI_CONFIG_STORAGE_KEY =
        'medicalUserscriptGlobalAiConfigV1';
    const GLOBAL_AI_REGISTRY_API_NAME =
        'MedicalUserscriptGlobalAiRegistry';
    const GLOBAL_AI_ADAPTER_QUEUE_NAME =
        '__medicalUserscriptGlobalAiAdapterQueueV1';
    const GLOBAL_AI_REGISTRY_READY_EVENT_NAME =
        'medical-userscript-global-ai-registry-ready';
    const GLOBAL_AI_ADAPTER_CHANGED_EVENT_NAME =
        'medical-userscript-global-ai-adapter-changed';
    const GLOBAL_AI_CONFIG_CHANGED_EVENT_NAME =
        'medical-userscript-global-ai-config-changed';

    const GLOBAL_AI_DEFAULT_SETTINGS = {
        enabled: false,
        provider: 'deepseek',
        mode: 'follow',
        deepseekDirectModel: 'deepseek-v4-flash',
        deepseekReasoningModel: 'deepseek-v4-flash',
        glmDirectModel: 'glm-5.2',
        glmReasoningModel: 'glm-5.3',
        glmReasoningEffort: 'max',
        openaiDirectModel: 'gpt-5.6-luna',
        openaiReasoningModel: 'gpt-5.6-sol',
        openaiReasoningEffort: 'high'
    };

    const globalAiAdapters = new Map();
    const globalAiSessionSecrets = {
        deepseek: '',
        glm: '',
        openai: ''
    };

    function normalizeGlobalAiSettings(value) {
        const source = value && typeof value === 'object' && !Array.isArray(value)
            ? value
            : {};
        const result = Object.assign({}, GLOBAL_AI_DEFAULT_SETTINGS, source);
        result.enabled = result.enabled === true;
        result.provider = ['deepseek', 'glm', 'openai'].includes(result.provider)
            ? result.provider
            : 'deepseek';
        result.mode = ['follow', 'direct', 'reasoning'].includes(result.mode)
            ? result.mode
            : 'follow';
        [
            'deepseekDirectModel',
            'deepseekReasoningModel',
            'glmDirectModel',
            'glmReasoningModel',
            'glmReasoningEffort',
            'openaiDirectModel',
            'openaiReasoningModel',
            'openaiReasoningEffort'
        ].forEach(function (key) {
            result[key] = String(
                result[key] || GLOBAL_AI_DEFAULT_SETTINGS[key]
            ).trim() || GLOBAL_AI_DEFAULT_SETTINGS[key];
        });
        if (!['low', 'medium', 'high', 'xhigh', 'max'].includes(result.openaiReasoningEffort)) {
            result.openaiReasoningEffort = 'high';
        }
        return result;
    }

    function syncGlobalAiConfigToSharedStorage(value) {
        const normalized = normalizeGlobalAiSettings(value);
        try {
            localStorage.setItem(
                GLOBAL_AI_CONFIG_STORAGE_KEY,
                JSON.stringify(normalized)
            );
            document.dispatchEvent(
                new CustomEvent(
                    GLOBAL_AI_CONFIG_CHANGED_EVENT_NAME,
                    { detail: { updatedAt: Date.now() } }
                )
            );
        } catch (error) {
            console.warn('[全局AI调用管理] 共享策略写入失败：', error);
        }
        return normalized;
    }

    function notifyGlobalAiAdapterChanged() {
        try {
            document.dispatchEvent(
                new CustomEvent(
                    GLOBAL_AI_ADAPTER_CHANGED_EVENT_NAME,
                    { detail: { count: globalAiAdapters.size, time: Date.now() } }
                )
            );
        } catch (error) {
            // 页面切换时忽略。
        }
    }

    function registerGlobalAiAdapter(adapter) {
        if (!adapter || typeof adapter !== 'object') {
            throw new Error('全局AI适配器必须是对象。');
        }
        const key = String(adapter.key || '').trim();
        if (!key) {
            throw new Error('全局AI适配器缺少key。');
        }
        if (
            typeof adapter.setApiKey !== 'function' ||
            typeof adapter.hasApiKey !== 'function'
        ) {
            throw new Error('全局AI适配器“' + key + '”缺少密钥读写接口。');
        }
        globalAiAdapters.set(key, adapter);

        ['deepseek', 'glm', 'openai'].forEach(function (provider) {
            const secret = String(globalAiSessionSecrets[provider] || '').trim();
            if (!secret) return;
            try {
                adapter.setApiKey(provider, secret);
            } catch (error) {
                console.warn('[全局AI调用管理] 延迟同步密钥失败：', key, provider, error);
            }
        });

        notifyGlobalAiAdapterChanged();
        return true;
    }

    function installGlobalAiRegistry() {
        const api = {
            register: registerGlobalAiAdapter
        };
        try {
            window[GLOBAL_AI_REGISTRY_API_NAME] = api;
            const queued = Array.isArray(window[GLOBAL_AI_ADAPTER_QUEUE_NAME])
                ? window[GLOBAL_AI_ADAPTER_QUEUE_NAME].slice()
                : [];
            window[GLOBAL_AI_ADAPTER_QUEUE_NAME] = [];
            queued.forEach(function (adapter) {
                try {
                    registerGlobalAiAdapter(adapter);
                } catch (error) {
                    console.warn('[全局AI调用管理] 预注册适配器无效：', error);
                }
            });
            document.dispatchEvent(
                new CustomEvent(GLOBAL_AI_REGISTRY_READY_EVENT_NAME)
            );
        } catch (error) {
            console.warn('[全局AI调用管理] 注册中心初始化失败：', error);
        }
    }

    installGlobalAiRegistry();

