    function builtInChargeItemCatalog() {
        return BUILTIN_CHARGE_ITEM_CATALOG_ROWS
            .map(function (row) {
                return {
                    name: row[0] || '',
                    unit: row[1] || '',
                    price:
                        row[2] == null
                            ? ''
                            : String(row[2]),
                    enabled: true
                };
            });
    }

