    async function collectScriptSourceBackupComponents(
        reason
    ) {
        const sources = [];
        const skipped = [];
        const providers =
            Array.from(
                scriptSourceBackupProviders.values()
            );

        for (
            let index = 0;
            index < providers.length;
            index += 1
        ) {
            const provider =
                providers[index];

            try {
                const raw =
                    await Promise.resolve(
                        provider.exportSource({
                            reason:
                                String(
                                    reason ||
                                    'source-backup'
                                )
                        })
                    );

                const sourceText =
                    typeof raw === 'string'
                        ? raw
                        : String(
                            raw &&
                            (
                                raw.source ||
                                raw.text
                            ) ||
                            ''
                        );

                if (!sourceText.trim()) {
                    throw new Error(
                        '源码提供器返回空内容。'
                    );
                }

                const maximum =
                    16 *
                    1024 *
                    1024;

                const bytes =
                    new TextEncoder()
                        .encode(
                            sourceText
                        )
                        .length;

                if (bytes > maximum) {
                    throw new Error(
                        '单个脚本源码超过16MB安全上限。'
                    );
                }

                let fileName =
                    typeof raw === 'object' &&
                    raw
                        ? String(
                            raw.fileName ||
                            provider.fileName
                        )
                        : provider.fileName;

                fileName =
                    fileName
                        .replace(/[\\\/]/g, '_')
                        .trim();

                if (
                    !fileName ||
                    !/\.(?:user\.js|js|txt)$/i
                        .test(fileName)
                ) {
                    fileName =
                        provider.id +
                        (
                            provider.version
                                ? '_v' +
                                    provider.version
                                : ''
                        ) +
                        '.user.js';
                }

                sources.push({
                    id: provider.id,
                    name: provider.name,
                    version: provider.version,
                    role: provider.role,
                    fileName: fileName,
                    bytes: bytes,
                    source: sourceText
                });
            } catch (error) {
                skipped.push({
                    id: provider.id,
                    name: provider.name,
                    version: provider.version,
                    message:
                        String(
                            error &&
                            error.message ||
                            error
                        )
                });
            }
        }

        sources.sort(
            function (first, second) {
                return String(first.id)
                    .localeCompare(
                        String(second.id)
                    );
            }
        );

        return {
            sources: sources,
            skipped: skipped
        };
    }

    function scriptSourceProviderSignature() {
        return listScriptSourceBackupProviders()
            .map(
                function (item) {
                    return (
                        item.id +
                        '@' +
                        item.version +
                        ':' +
                        item.fileName
                    );
                }
            )
            .join('|');
    }

    installScriptSourceBackupRegistry();

    registerScriptSourceBackupProvider({
        id: 'manager',
        name:
            '智慧医疗－七脚本隔离与悬浮框风格管理器',
        version:
            '3.7.3.5.32',
        role:
            'manager',
        fileName:
            '智慧医疗－七脚本隔离与悬浮框风格管理器_v3.7.3.5.32.user.js',
        exportSource:
            managerSelfSourceText
    });

    async function collectBusinessBackupComponents(
        reason,
        options
    ) {
        const source =
            options &&
            typeof options === 'object'
                ? options
                : {};

        const components = {};
        const skipped = [];

        for (
            let index = 0;
            index < BUSINESS_BACKUP_COMPONENT_CONFIGS.length;
            index += 1
        ) {
            const config =
                BUSINESS_BACKUP_COMPONENT_CONFIGS[index];

            const adapter =
                businessBackupAdapters.get(
                    config.key
                );

            if (!adapter) {
                skipped.push({
                    key: config.key,
                    name: config.name,
                    reason: 'adapter-not-installed'
                });
                continue;
            }

            try {
                if (
                    adapter.isBusy &&
                    await Promise.resolve(
                        adapter.isBusy()
                    )
                ) {
                    skipped.push({
                        key: config.key,
                        name: adapter.name,
                        reason: 'business-task-busy'
                    });
                    continue;
                }

                const data =
                    await Promise.resolve(
                        adapter.exportData({
                            reason:
                                String(
                                    reason ||
                                    'backup'
                                ),
                            includeSensitive:
                                source.includeSensitive ===
                                    true,
                            origin:
                                String(
                                    location.origin ||
                                    ''
                                ),
                            schemaVersion:
                                SETTINGS_BACKUP_SCHEMA_VERSION
                        })
                    );

                if (data === undefined) {
                    skipped.push({
                        key: config.key,
                        name: adapter.name,
                        reason: 'adapter-returned-no-data'
                    });
                    continue;
                }

                const safeData =
                    JSON.parse(
                        JSON.stringify(data)
                    );

                let description = '';

                if (adapter.describeData) {
                    description =
                        String(
                            await Promise.resolve(
                                adapter.describeData(
                                    safeData
                                )
                            ) ||
                            ''
                        );
                }

                components[
                    config.key
                ] = {
                    key: config.key,
                    name: adapter.name,
                    scriptVersion:
                        adapter.version,
                    adapterVersion:
                        adapter.adapterVersion,
                    exportedAt:
                        new Date()
                            .toISOString(),
                    description:
                        description,
                    data: safeData
                };
            } catch (error) {
                skipped.push({
                    key: config.key,
                    name: adapter.name,
                    reason: 'export-failed',
                    message:
                        String(
                            error &&
                            error.message ||
                            error
                        )
                });
            }
        }

        return {
            components: components,
            skipped: skipped
        };
    }

    function normalizeBusinessBackupComponents(
        value
    ) {
        const source =
            value &&
            typeof value === 'object' &&
            !Array.isArray(value)
                ? value
                : {};

        const result = {};

        BUSINESS_BACKUP_COMPONENT_CONFIGS.forEach(
            function (config) {
                const component =
                    source[config.key];

                if (
                    !component ||
                    typeof component !== 'object' ||
                    Array.isArray(component) ||
                    !Object.prototype
                        .hasOwnProperty.call(
                            component,
                            'data'
                        )
                ) {
                    return;
                }

                result[config.key] = {
                    key: config.key,
                    name:
                        String(
                            component.name ||
                            config.name
                        ),
                    scriptVersion:
                        String(
                            component.scriptVersion ||
                            ''
                        ),
                    adapterVersion:
                        Math.max(
                            1,
                            Number(
                                component.adapterVersion
                            ) ||
                            1
                        ),
                    exportedAt:
                        String(
                            component.exportedAt ||
                            ''
                        ),
                    description:
                        String(
                            component.description ||
                            ''
                        ),
                    data:
                        cloneObject(
                            component.data
                        )
                };
            }
        );

        return result;
    }

    async function restoreBusinessBackupComponents(
        backup,
        reason
    ) {
        const components =
            normalizeBusinessBackupComponents(
                backup.businessScripts
            );

        const result = {
            restored: [],
            skipped: [],
            failed: []
        };

        const keys =
            Object.keys(components);

        for (
            let index = 0;
            index < keys.length;
            index += 1
        ) {
            const key = keys[index];
            const component =
                components[key];

            const adapter =
                businessBackupAdapters.get(key);

            if (
                !adapter ||
                !adapter.importData
            ) {
                result.skipped.push({
                    key: key,
                    name: component.name,
                    reason:
                        adapter
                            ? 'adapter-export-only'
                            : 'adapter-not-installed'
                });
                continue;
            }

            try {
                if (
                    adapter.isBusy &&
                    await Promise.resolve(
                        adapter.isBusy()
                    )
                ) {
                    result.skipped.push({
                        key: key,
                        name: component.name,
                        reason: 'business-task-busy'
                    });
                    continue;
                }

                const context = {
                    reason:
                        String(
                            reason ||
                            'backup-restore'
                        ),
                    sourceVersion:
                        component.scriptVersion,
                    adapterVersion:
                        component.adapterVersion,
                    backupCreatedAt:
                        String(
                            backup.createdAt ||
                            ''
                        ),
                    origin:
                        String(
                            backup.origin ||
                            ''
                        )
                };

                if (adapter.validateData) {
                    const validation =
                        await Promise.resolve(
                            adapter.validateData(
                                cloneObject(
                                    component.data
                                ),
                                context
                            )
                        );

                    if (
                        validation === false ||
                        typeof validation ===
                            'string'
                    ) {
                        throw new Error(
                            typeof validation ===
                                'string'
                                ? validation
                                : '业务脚本拒绝了该备份数据。'
                        );
                    }
                }

                await Promise.resolve(
                    adapter.importData(
                        cloneObject(
                            component.data
                        ),
                        context
                    )
                );

                result.restored.push({
                    key: key,
                    name: component.name
                });
            } catch (error) {
                result.failed.push({
                    key: key,
                    name: component.name,
                    message:
                        String(
                            error &&
                            error.message ||
                            error
                        )
                });
            }
        }

        return result;
    }

    function dispatchWebdavStatus(
        message,
        type,
        extra
    ) {
        try {
            document.dispatchEvent(
                new CustomEvent(
                    WEBDAV_STATUS_EVENT_NAME,
                    {
                        detail:
                            Object.assign(
                                {
                                    message:
                                        String(
                                            message ||
                                            ''
                                        ),
                                    type:
                                        String(
                                            type ||
                                            'normal'
                                        )
                                },
                                extra || {}
                            )
                    }
                )
            );
        } catch (error) {
            // 状态事件失败不影响备份结果。
        }
    }

    function cancelScheduledWebdavAutomaticBackup() {
        clearTimeout(
            webdavAutomaticBackupTimer
        );

        webdavAutomaticBackupTimer =
            null;
    }

    function scheduleWebdavAutomaticBackup(
        reason
    ) {
        const config =
            loadWebdavConfig();

        if (
            !config.autoUpload ||
            !config.endpoint
        ) {
            return;
        }

        cancelScheduledWebdavAutomaticBackup();

        webdavAutomaticBackupTimer =
            setTimeout(
                async function () {
                    webdavAutomaticBackupTimer =
                        null;

                    if (
                        webdavAutomaticBackupInFlight ||
                        CONFIGS.some(
                            function (configItem) {
                                return isConfigBusy(
                                    configItem
                                );
                            }
                        )
                    ) {
                        scheduleWebdavAutomaticBackup(
                            reason
                        );
                        return;
                    }

                    webdavAutomaticBackupInFlight =
                        true;

                    dispatchWebdavStatus(
                        '检测到设置变动，正在创建WebDAV自动备份……',
                        'pending'
                    );

                    try {
                        const result =
                            await uploadSuiteBackupToWebdav(
                                config,
                                'automatic-' +
                                String(
                                    reason ||
                                    'settings-change'
                                ),
                                {
                                    includeSensitive: false,
                                    remoteFileName:
                                        webdavAutomaticBackupFileName(
                                            config
                                        ),
                                    allowOverwrite: true
                                }
                            );

                        dispatchWebdavStatus(
                            'WebDAV自动备份已完成：' +
                            result.fileName,
                            'success',
                            {
                                refreshList: true
                            }
                        );
                    } catch (error) {
                        dispatchWebdavStatus(
                            'WebDAV自动备份失败：' +
                            String(
                                error &&
                                error.message ||
                                error
                            ),
                            'error'
                        );
                    } finally {
                        webdavAutomaticBackupInFlight =
                            false;
                    }
                },
                15000
            );
    }


    function cancelScheduledWebdavSourceAutomaticBackup() {
        clearTimeout(
            webdavSourceAutomaticBackupTimer
        );

        webdavSourceAutomaticBackupTimer =
            null;
    }

    function scheduleWebdavSourceAutomaticBackup(
        reason
    ) {
        const config =
            loadWebdavConfig();

        if (
            !config.autoUpload ||
            !config.sourceAutoUpload ||
            !config.endpoint
        ) {
            return;
        }

        cancelScheduledWebdavSourceAutomaticBackup();

        webdavSourceAutomaticBackupTimer =
            setTimeout(
                async function () {
                    webdavSourceAutomaticBackupTimer =
                        null;

                    if (
                        webdavSourceAutomaticBackupInFlight ||
                        webdavAutomaticBackupInFlight
                    ) {
                        scheduleWebdavSourceAutomaticBackup(
                            reason
                        );
                        return;
                    }

                    const signature =
                        scriptSourceProviderSignature();

                    if (!signature) {
                        return;
                    }

                    let previousSignature = '';

                    try {
                        previousSignature =
                            String(
                                localStorage.getItem(
                                    SCRIPT_SOURCE_BACKUP_SIGNATURE_STORAGE_KEY
                                ) ||
                                ''
                            );
                    } catch (error) {
                        previousSignature = '';
                    }

                    if (
                        previousSignature ===
                        signature
                    ) {
                        return;
                    }

                    webdavSourceAutomaticBackupInFlight =
                        true;

                    dispatchWebdavStatus(
                        '检测到脚本版本变化，正在同步WebDAV源码快照……',
                        'pending'
                    );

                    try {
                        const result =
                            await uploadScriptSourcesToWebdav(
                                config,
                                'automatic-source-' +
                                String(
                                    reason ||
                                    'version-change'
                                )
                            );

                        try {
                            localStorage.setItem(
                                SCRIPT_SOURCE_BACKUP_SIGNATURE_STORAGE_KEY,
                                signature
                            );
                        } catch (error) {
                            // 记录失败不影响本次上传。
                        }

                        dispatchWebdavStatus(
                            'WebDAV脚本源码自动备份完成：' +
                            result.uploaded.length +
                            '个脚本，' +
                            (
                                result.skipped.length
                                    ? '跳过' +
                                        result.skipped.length +
                                        '个。'
                                    : '无跳过项。'
                            ),
                            'success'
                        );
                    } catch (error) {
                        dispatchWebdavStatus(
                            'WebDAV脚本源码自动备份失败：' +
                            String(
                                error &&
                                error.message ||
                                error
                            ),
                            'error'
                        );
                    } finally {
                        webdavSourceAutomaticBackupInFlight =
                            false;
                    }
                },
                12000
            );
    }

    /******************************************************************
     * v3.7.3.5.19：统一缓存管理注册表与旧localStorage读取兼容桥
     ******************************************************************/
    function normalizeCacheManagementAdapter(adapter) {
        if (
            !adapter ||
            typeof adapter !== 'object' ||
            Array.isArray(adapter)
        ) {
            throw new Error('缓存管理适配器必须是对象。');
        }

        const key = String(adapter.key || '').trim();
        if (!key) {
            throw new Error('缓存管理适配器缺少key。');
        }

        if (typeof adapter.listCaches !== 'function') {
            throw new Error('缓存管理适配器“' + key + '”缺少listCaches。');
        }

        return {
            key: key,
            name: String(adapter.name || key),
            version: String(adapter.version || ''),
            adapterVersion: Number(adapter.adapterVersion) || 1,
            containsPatientData: adapter.containsPatientData !== false,
            listCaches: adapter.listCaches,
            exportCaches:
                typeof adapter.exportCaches === 'function'
                    ? adapter.exportCaches
                    : null,
            validateCaches:
                typeof adapter.validateCaches === 'function'
                    ? adapter.validateCaches
                    : null,
            importCaches:
                typeof adapter.importCaches === 'function'
                    ? adapter.importCaches
                    : null,
            clearCaches:
                typeof adapter.clearCaches === 'function'
                    ? adapter.clearCaches
                    : null,
            readLegacyStorageKey:
                typeof adapter.readLegacyStorageKey === 'function'
                    ? adapter.readLegacyStorageKey
                    : null,
            isBusy:
                typeof adapter.isBusy === 'function'
                    ? adapter.isBusy
                    : function () { return false; }
        };
    }

    function registerCacheManagementAdapter(adapter) {
        const normalized =
            normalizeCacheManagementAdapter(adapter);

        cacheManagementAdapters.set(
            normalized.key,
            normalized
        );

        try {
            document.dispatchEvent(
                new CustomEvent(
                    CACHE_MANAGEMENT_CHANGED_EVENT_NAME,
                    {
                        detail: {
                            adapterKey: normalized.key,
                            reason: 'adapter-registered',
                            time: Date.now()
                        }
                    }
                )
            );
        } catch (error) {
            // UI尚未创建时无需处理。
        }

        return true;
    }

    function listCacheManagementAdapters() {
        return Array.from(
            cacheManagementAdapters.values()
        ).map(function (adapter) {
            return {
                key: adapter.key,
                name: adapter.name,
                version: adapter.version,
                containsPatientData:
                    adapter.containsPatientData,
                canExport: Boolean(adapter.exportCaches),
                canImport: Boolean(adapter.importCaches),
                canClear: Boolean(adapter.clearCaches)
            };
        });
    }

    function installCacheManagementRegistry() {
        const api = {
            apiVersion: 1,
            register: registerCacheManagementAdapter,
            unregister: function (key) {
                const removed = cacheManagementAdapters.delete(
                    String(key || '')
                );
                if (removed) {
                    try {
                        document.dispatchEvent(
                            new CustomEvent(
                                CACHE_MANAGEMENT_CHANGED_EVENT_NAME,
                                {
                                    detail: {
                                        adapterKey: String(key || ''),
                                        reason: 'adapter-unregistered',
                                        time: Date.now()
                                    }
                                }
                            )
                        );
                    } catch (error) {}
                }
                return removed;
            },
            list: listCacheManagementAdapters,
            notifyChanged: function (key) {
                try {
                    document.dispatchEvent(
                        new CustomEvent(
                            CACHE_MANAGEMENT_CHANGED_EVENT_NAME,
                            {
                                detail: {
                                    adapterKey: String(key || ''),
                                    reason: 'cache-changed',
                                    time: Date.now()
                                }
                            }
                        )
                    );
                } catch (error) {}
            },
            contract: {
                required: ['key', 'listCaches'],
                optional: [
                    'name',
                    'version',
                    'adapterVersion',
                    'containsPatientData',
                    'exportCaches',
                    'validateCaches',
                    'importCaches',
                    'clearCaches',
                    'readLegacyStorageKey',
                    'isBusy'
                ]
            }
        };

        try {
            Object.defineProperty(
                window,
                CACHE_MANAGEMENT_API_NAME,
                {
                    configurable: true,
                    enumerable: false,
                    writable: false,
                    value: api
                }
            );
        } catch (error) {
            window[CACHE_MANAGEMENT_API_NAME] = api;
        }

        const queue = Array.isArray(
            window[CACHE_MANAGEMENT_QUEUE_NAME]
        )
            ? window[CACHE_MANAGEMENT_QUEUE_NAME]
            : [];

        queue.slice().forEach(function (adapter) {
            try {
                registerCacheManagementAdapter(adapter);
            } catch (error) {
                console.warn(
                    '[统一缓存管理] 预注册适配器无效：',
                    error
                );
            }
        });

        const originalPush = queue.push.bind(queue);
        queue.push = function () {
            Array.from(arguments).forEach(function (adapter) {
                try {
                    registerCacheManagementAdapter(adapter);
                } catch (error) {
                    console.warn(
                        '[统一缓存管理] 新适配器注册失败：',
                        error
                    );
                }
            });
            return originalPush.apply(queue, arguments);
        };

        window[CACHE_MANAGEMENT_QUEUE_NAME] = queue;

        try {
            document.dispatchEvent(
                new CustomEvent(
                    CACHE_MANAGEMENT_READY_EVENT_NAME,
                    {
                        detail: {
                            apiVersion: 1,
                            time: Date.now()
                        }
                    }
                )
            );
        } catch (error) {}
    }

    function installCacheLegacyLocalStorageReadBridge() {
        if (
            window.__medicalUserscriptCacheLegacyGetItemBridgeV1__
        ) {
            return;
        }

        const StorageCtor = window.Storage;
        if (!StorageCtor || !StorageCtor.prototype) {
            return;
        }

        const nativeGetItem = StorageCtor.prototype.getItem;
        if (typeof nativeGetItem !== 'function') {
            return;
        }

        window.__medicalUserscriptCacheLegacyGetItemBridgeV1__ = true;

        StorageCtor.prototype.getItem = function (key) {
            const storageKey = String(key == null ? '' : key);

            if (this === window.localStorage && storageKey) {
                const adapters = Array.from(
                    cacheManagementAdapters.values()
                );

                for (
                    let index = 0;
                    index < adapters.length;
                    index += 1
                ) {
                    const adapter = adapters[index];
                    if (!adapter.readLegacyStorageKey) {
                        continue;
                    }

                    try {
                        const bridged =
                            adapter.readLegacyStorageKey(storageKey);

                        if (
                            bridged !== null &&
                            bridged !== undefined
                        ) {
                            return String(bridged);
                        }
                    } catch (error) {
                        /*
                         * 单个适配器故障必须退回浏览器原始localStorage，
                         * 不能影响HIS页面和其他脚本的普通存储读取。
                         */
                    }
                }
            }

            return nativeGetItem.call(this, key);
        };
    }

    installBusinessBackupRegistry();
    installCacheManagementRegistry();
    installCacheLegacyLocalStorageReadBridge();


    /******************************************************************
     * 二-A、跨脚本共享药名知识库
     ******************************************************************/

    function normalizeKnowledgeText(
        value
    ) {
        return String(
            value == null
                ? ''
                : value
        )
            .replace(/\u00a0/g, ' ')
            .replace(/[★☆*]/g, '')
            .replace(/[（）()【】\[\]{}]/g, '')
            .replace(/[\s·•・,，;；:：\/\\_-]+/g, '')
            .toLowerCase()
            .trim();
    }


    /*
     * 无外部依赖的中文拼音首字母近似转换。
     * 使用中文排序边界判定声母，适合药名联想检索；
     * 多音字按常用排序读音处理，英文和数字原样保留。
     */
    function westernDrugPinyinInitials(
        value
    ) {
        const source =
            plainKnowledgeText(value);

        if (!source) {
            return '';
        }

        const boundaries =
            '阿芭擦搭蛾发噶哈击喀垃妈拿哦啪期然撒塌挖昔压匝';

        const initials =
            'ABCDEFGHJKLMNOPQRSTWXYZ';

        let result = '';

        Array.from(source)
            .forEach(function (character) {
                if (/[a-z0-9]/i.test(character)) {
                    result += character.toUpperCase();
                    return;
                }

                if (
                    /[\s★☆*（）()【】\[\]{}·•・,，;；:：\/\\_\-+%.]/
                        .test(character)
                ) {
                    return;
                }

                let matched = '';

                for (
                    let index = boundaries.length - 1;
                    index >= 0;
                    index -= 1
                ) {
                    try {
                        if (
                            character.localeCompare(
                                boundaries[index],
                                'zh-CN',
                                {
                                    sensitivity: 'base'
                                }
                            ) >= 0
                        ) {
                            matched =
                                initials[index] || '';
                            break;
                        }
                    }
                    catch (error) {
                        if (
                            character.localeCompare(
                                boundaries[index]
                            ) >= 0
                        ) {
                            matched =
                                initials[index] || '';
                            break;
                        }
                    }
                }

                result += matched;
            });

        return result
            .replace(/[^A-Z0-9]/g, '');
    }

    function plainKnowledgeText(
        value
    ) {
        return String(
            value == null
                ? ''
                : value
        )
            .replace(/\u00a0/g, ' ')
            .replace(/\r/g, '')
            .replace(/[ \t]+/g, ' ')
            .trim();
    }

    function normalizeAliasList(
        value
    ) {
        const source =
            Array.isArray(value)
                ? value
                : String(value || '')
                    .split(/[|｜、,，;；\n]+/);

        const result = [];
        const seen = new Set();

        source.forEach(function (item) {
            const textValue =
                plainKnowledgeText(item);

            const key =
                normalizeKnowledgeText(
                    textValue
                );

            if (
                !textValue ||
                !key ||
                seen.has(key)
            ) {
                return;
            }

            seen.add(key);
            result.push(textValue);
        });

        return result;
    }

    function normalizeTcmMappingEntry(
        raw
    ) {
        const source =
            raw &&
            typeof raw === 'object'
                ? raw
                : {};

        const from =
            plainKnowledgeText(
                source.from ||
                source.source ||
                source.alias ||
                source.genericName ||
                source.name
            );

        const to =
            plainKnowledgeText(
                source.to ||
                source.target ||
                source.localName ||
                source.hospitalName ||
                source.searchName
            );

        if (!from || !to) {
            return null;
        }

        return {
            from: from,
            to: to,
            aliases:
                normalizeAliasList(
                    source.aliases ||
                    source.otherNames ||
                    []
                ),
            enabled:
                source.enabled !== false,
            note:
                plainKnowledgeText(
                    source.note ||
                    source.remark
                )
        };
    }

    function normalizeDiagnosisMappingEntry(
        raw
    ) {
        const source =
            raw &&
            typeof raw === 'object'
                ? raw
                : {};

        const from =
            plainKnowledgeText(
                source.from ||
                source.source ||
                source.alias ||
                source.standardName ||
                source.diagnosisName ||
                source.name
            );

        const to =
            plainKnowledgeText(
                source.to ||
                source.target ||
                source.localName ||
                source.hospitalName ||
                source.searchName
            );

        if (!from || !to) {
            return null;
        }

        return {
            from: from,
            to: to,
            aliases:
                normalizeAliasList(
                    source.aliases ||
                    source.otherNames ||
                    []
                ),
            enabled:
                source.enabled !== false,
            note:
                plainKnowledgeText(
                    source.note ||
                    source.remark
                )
        };
    }

    function normalizeWesternDrugEntry(
        raw
    ) {
        const source =
            raw &&
            typeof raw === 'object'
                ? raw
                : {};

        const name =
            plainKnowledgeText(
                source.name ||
                source.drugName ||
                source.genericName ||
                source.通用名 ||
                source.名称 ||
                source.药品名称
            );

        const searchName =
            plainKnowledgeText(
                source.searchName ||
                source.lookupName ||
                source.mnemonic ||
                source.pinyin ||
                source.检索名 ||
                source.拼音 ||
                source.简拼 ||
                name
            );

        if (!name && !searchName) {
            return null;
        }

        return {
            name:
                name || searchName,
            searchName:
                searchName || name,
            specification:
                plainKnowledgeText(
                    source.specification ||
                    source.spec ||
                    source.规格
                ),
            unit:
                plainKnowledgeText(
                    source.unit ||
                    source.单位
                ),
            manufacturer:
                plainKnowledgeText(
                    source.manufacturer ||
                    source.factory ||
                    source.生产厂家 ||
                    source.厂家
                ),
            code:
                plainKnowledgeText(
                    source.code ||
                    source.drugCode ||
                    source.药品编码 ||
                    source.代码 ||
                    source.国家医保代码
                ),
            aliases:
                normalizeAliasList(
                    source.aliases ||
                    source.otherNames ||
                    source.别名 ||
                    []
                ),
            enabled:
                source.enabled !== false,
            note:
                plainKnowledgeText(
                    source.note ||
                    source.remark ||
                    source.备注
                )
        };
    }


    function normalizeChargeItemEntry(
        raw
    ) {
        const source =
            raw &&
            typeof raw === 'object'
                ? raw
                : {};

        const name =
            plainKnowledgeText(
                source.name ||
                source.chargeItemName ||
                source.itemName ||
                source.projectName ||
                source.收费项目名称 ||
                source.项目名称 ||
                source.名称
            );

        if (!name) {
            return null;
        }

        let unit =
            plainKnowledgeText(
                source.unit ||
                source.billingUnit ||
                source.pricingUnit ||
                source.计价单位 ||
                source.单位
            );

        if (unit === '22') {
            unit = '';
        }

        const rawPrice =
            source.price != null
                ? source.price
                : source.unitPrice != null
                    ? source.unitPrice
                    : source.单价;

        const price =
            rawPrice == null
                ? ''
                : plainKnowledgeText(
                    rawPrice
                );

        return {
            name: name,
            unit: unit,
            price: price,
            enabled:
                source.enabled !== false
        };
    }

    function chargeItemIdentity(
        item
    ) {
        const source =
            item &&
            typeof item === 'object'
                ? item
                : {};

        return [
            normalizeKnowledgeText(
                source.name
            ),
            normalizeKnowledgeText(
                source.unit
            ),
            normalizeKnowledgeText(
                source.price
            )
        ].join(':');
    }

    function mergeChargeItemLists() {
        const result = [];
        const indexByIdentity =
            new Map();

        Array.from(arguments)
            .forEach(function (list) {
                (
                    Array.isArray(list)
                        ? list
                        : []
                )
                    .map(
                        normalizeChargeItemEntry
                    )
                    .filter(Boolean)
                    .forEach(function (item) {
                        const identity =
                            chargeItemIdentity(
                                item
                            );

                        if (!identity) {
                            return;
                        }

                        const existingIndex =
                            indexByIdentity.get(
                                identity
                            );

                        if (
                            existingIndex ===
                            undefined
                        ) {
                            indexByIdentity.set(
                                identity,
                                result.length
                            );

                            result.push(
                                item
                            );

                            return;
                        }

                        const existing =
                            result[
                                existingIndex
                            ];

                        if (
                            plainKnowledgeText(
                                item.name
                            )
                        ) {
                            existing.name =
                                item.name;
                        }

                        if (
                            plainKnowledgeText(
                                item.unit
                            )
                        ) {
                            existing.unit =
                                item.unit;
                        }

                        if (
                            item.price !== ''
                        ) {
                            existing.price =
                                item.price;
                        }

                        existing.enabled =
                            item.enabled !== false;
                    });
            });

        return result;
    }

    function deduplicateByKeys(
        list,
        keyBuilder
    ) {
        const result = [];
        const seen = new Set();

        list.forEach(function (item) {
            const keys =
                keyBuilder(item)
                    .map(normalizeKnowledgeText)
                    .filter(Boolean);

            const primary =
                keys[0] || '';

            if (
                !primary ||
                seen.has(primary)
            ) {
                return;
            }

            keys.forEach(function (key) {
                seen.add(key);
            });

            result.push(item);
        });

        return result;
    }

    function westernDrugIdentity(
        item
    ) {
        const source =
            item &&
            typeof item === 'object'
                ? item
                : {};

        const code =
            normalizeKnowledgeText(
                source.code
            );

        if (code) {
            return 'code:' + code;
        }

        return [
            'item',
            normalizeKnowledgeText(
                source.name ||
                source.searchName
            ),
            normalizeKnowledgeText(
                source.specification
            ),
            normalizeKnowledgeText(
                source.manufacturer
            )
        ].join(':');
    }

    function mergeWesternDrugLists() {
        const result = [];
        const indexByIdentity =
            new Map();

        Array.from(arguments)
            .forEach(function (list) {
                (
                    Array.isArray(list)
                        ? list
                        : []
                )
                    .map(
                        normalizeWesternDrugEntry
                    )
                    .filter(Boolean)
                    .forEach(function (item) {
                        const identity =
                            westernDrugIdentity(
                                item
                            );

                        if (!identity) {
                            return;
                        }

                        const existingIndex =
                            indexByIdentity.get(
                                identity
                            );

                        if (
                            existingIndex ===
                            undefined
                        ) {
                            indexByIdentity.set(
                                identity,
                                result.length
                            );

                            result.push(
                                item
                            );

                            return;
                        }

                        const existing =
                            result[
                                existingIndex
                            ];

                        [
                            'name',
                            'searchName',
                            'specification',
                            'unit',
                            'manufacturer',
                            'code',
                            'note'
                        ].forEach(function (key) {
                            if (
                                plainKnowledgeText(
                                    item[key]
                                )
                            ) {
                                existing[key] =
                                    item[key];
                            }
                        });

                        existing.aliases =
                            normalizeAliasList(
                                (
                                    existing.aliases ||
                                    []
                                ).concat(
                                    item.aliases ||
                                    []
                                )
                            );

                        existing.enabled =
                            item.enabled !== false;
                    });
            });

        return result;
    }

    function normalizeSharedLibrary(
        raw
    ) {
        const source =
            raw &&
            typeof raw === 'object'
                ? raw
                : {};

        const sourceSettings =
            source.settings &&
            typeof source.settings === 'object'
                ? source.settings
                : {};

        const tcmMappings =
            deduplicateByKeys(
                (
                    Array.isArray(
                        source.tcmMappings
                    )
                        ? source.tcmMappings
                        : []
                )
                    .map(normalizeTcmMappingEntry)
                    .filter(Boolean),
                function (item) {
                    return [
                        item.from,
                        item.to
                    ].concat(
                        item.aliases || []
                    );
                }
            );

        const diagnosisMappings =
            deduplicateByKeys(
                (
                    Array.isArray(
                        source.diagnosisMappings
                    )
                        ? source.diagnosisMappings
                        : []
                )
                    .map(normalizeDiagnosisMappingEntry)
                    .filter(Boolean),
                function (item) {
                    return [
                        item.from,
                        item.to
                    ].concat(
                        item.aliases || []
                    );
                }
            );

        const westernDrugs =
            mergeWesternDrugLists(
                Array.isArray(
                    source.westernDrugs
                )
                    ? source.westernDrugs
                    : []
            );

        const chargeItems =
            mergeChargeItemLists(
                Array.isArray(
                    source.chargeItems
                )
                    ? source.chargeItems
                    : []
            );

        return {
            version: 4,
            updatedAt:
                plainKnowledgeText(
                    source.updatedAt
                ),
            builtinCatalogVersion:
                plainKnowledgeText(
                    source.builtinCatalogVersion
                ),
            builtinChargeCatalogVersion:
                plainKnowledgeText(
                    source.builtinChargeCatalogVersion
                ),
            settings: {
                enableTcmNameMapping:
                    Boolean(
                        sourceSettings
                            .enableTcmNameMapping
                    ),
                enableDiagnosisNameMapping:
                    sourceSettings
                        .enableDiagnosisNameMapping == null
                        ? true
                        : Boolean(
                            sourceSettings
                                .enableDiagnosisNameMapping
                        ),
                enableWesternDrugSuggestion:
                    Boolean(
                        sourceSettings
                            .enableWesternDrugSuggestion
                    ),
                enableWesternDrugPinyinInitials:
                    Boolean(
                        sourceSettings
                            .enableWesternDrugPinyinInitials
                    ),
                enableChargeItemSuggestion:
                    Boolean(
                        sourceSettings
                            .enableChargeItemSuggestion
                    ),
                enableChargeItemPinyinInitials:
                    Boolean(
                        sourceSettings
                            .enableChargeItemPinyinInitials
                    )
            },
            tcmMappings: tcmMappings,
            diagnosisMappings: diagnosisMappings,
            westernDrugs: westernDrugs,
            chargeItems: chargeItems
        };
    }


    function mergeBuiltInWesternCatalog(
        library,
        force
    ) {
        const target =
            normalizeSharedLibrary(
                library
            );

        if (
            !force &&
            target.builtinCatalogVersion ===
                BUILTIN_WESTERN_DRUG_CATALOG_VERSION
        ) {
            return {
                library: target,
                changed: false
            };
        }

        /*
         * 内置目录先进入，用户已经维护的记录后进入。
         * 相同药品ID或同一名称+规格+厂家时，用户记录优先覆盖，
         * 同时保留双方别名，避免脚本升级覆盖人工修订。
         */
        target.westernDrugs =
            mergeWesternDrugLists(
                builtInWesternDrugCatalog(),
                target.westernDrugs
            );

        target.builtinCatalogVersion =
            BUILTIN_WESTERN_DRUG_CATALOG_VERSION;

        target.updatedAt =
            new Date().toISOString();

        return {
            library: target,
            changed: true
        };
    }

    function mergeBuiltInChargeCatalog(
        library,
        force
    ) {
        const target =
            normalizeSharedLibrary(
                library
            );

        if (
            !force &&
            target.builtinChargeCatalogVersion ===
                BUILTIN_CHARGE_ITEM_CATALOG_VERSION
        ) {
            return {
                library: target,
                changed: false
            };
        }

        /*
         * 内置收费目录先进入，人工维护记录后进入。
         * 同名、同计价单位、同单价的项目会合并；人工记录优先。
         */
        target.chargeItems =
            mergeChargeItemLists(
                builtInChargeItemCatalog(),
                target.chargeItems
            );

        target.builtinChargeCatalogVersion =
            BUILTIN_CHARGE_ITEM_CATALOG_VERSION;

        target.updatedAt =
            new Date().toISOString();

        return {
            library: target,
            changed: true
        };
    }


    function loadSharedLibrary() {
        let normalized;

        try {
            const parsed =
                JSON.parse(
                    localStorage.getItem(
                        SHARED_LIBRARY_STORAGE_KEY
                    ) ||
                    'null'
                );

            normalized =
                normalizeSharedLibrary(
                    parsed ||
                    DEFAULT_SHARED_LIBRARY
                );
        }
        catch (error) {
            normalized =
                normalizeSharedLibrary(
                    DEFAULT_SHARED_LIBRARY
                );
        }

        const westernMerged =
            mergeBuiltInWesternCatalog(
                normalized,
                false
            );

        const chargeMerged =
            mergeBuiltInChargeCatalog(
                westernMerged.library,
                false
            );

        if (
            westernMerged.changed ||
            chargeMerged.changed
        ) {
            try {
                localStorage.setItem(
                    SHARED_LIBRARY_STORAGE_KEY,
                    JSON.stringify(
                        chargeMerged.library
                    )
                );
            }
            catch (error) {
                /*
                 * 自动迁移保存失败时仍返回内存中的目录，
                 * 用户可在管理器中导出或清理旧数据后再次保存。
                 */
            }
        }

        return chargeMerged.library;
    }



    let sharedLibrary =
        loadSharedLibrary();

    function sharedLibrarySummary() {
        return {
            tcmMappings:
                sharedLibrary
                    .tcmMappings
                    .filter(function (item) {
                        return item.enabled !== false;
                    })
                    .length,
            diagnosisMappings:
                sharedLibrary
                    .diagnosisMappings
                    .filter(function (item) {
                        return item.enabled !== false;
                    })
                    .length,
            westernDrugs:
                sharedLibrary
                    .westernDrugs
                    .filter(function (item) {
                        return item.enabled !== false;
                    })
                    .length,
            chargeItems:
                sharedLibrary
                    .chargeItems
                    .filter(function (item) {
                        return item.enabled !== false;
                    })
                    .length,
            enableTcmNameMapping:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableTcmNameMapping
                ),
            enableDiagnosisNameMapping:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableDiagnosisNameMapping
                ),
            enableWesternDrugSuggestion:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableWesternDrugSuggestion
                ),
            enableWesternDrugPinyinInitials:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableWesternDrugPinyinInitials
                ),
            enableChargeItemSuggestion:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableChargeItemSuggestion
                ),
            enableChargeItemPinyinInitials:
                Boolean(
                    sharedLibrary
                        .settings
                        .enableChargeItemPinyinInitials
                )
        };
    }


    function dispatchSharedLibraryChanged(
        reason
    ) {
        try {
            document.dispatchEvent(
                new CustomEvent(
                    SHARED_LIBRARY_EVENT_NAME,
                    {
                        detail: {
                            reason:
                                reason ||
                                'update',
                            storageKey:
                                SHARED_LIBRARY_STORAGE_KEY,
                            summary:
                                sharedLibrarySummary()
                        }
                    }
                )
            );
        }
        catch (error) {
            /* 旧浏览器中事件派发失败不影响存储。 */
        }
    }

    function saveSharedLibrary(
        reason
    ) {
        sharedLibrary =
            normalizeSharedLibrary(
                sharedLibrary
            );

        sharedLibrary.updatedAt =
            new Date().toISOString();

        try {
            localStorage.setItem(
                SHARED_LIBRARY_STORAGE_KEY,
                JSON.stringify(
                    sharedLibrary
                )
            );
        }
        catch (error) {
            throw new Error(
                '共享映射与联想库保存失败，可能已超过浏览器本地存储容量。'
            );
        }

        dispatchSharedLibraryChanged(
            reason
        );

        if (
            !/settings-backup|webdav-restore/i.test(
                String(reason || '')
            )
        ) {
            scheduleWebdavAutomaticBackup(
                'shared-library'
            );
        }
    }

    function createManagerBackupPayload(
        reason
    ) {
        return {
            schema:
                SETTINGS_BACKUP_SCHEMA,
            schemaVersion:
                SETTINGS_BACKUP_SCHEMA_VERSION,
            scriptVersion:
                '3.7.3.5.32',
            createdAt:
                new Date().toISOString(),
            reason:
                String(
                    reason ||
                    'manual-export'
                ),
            origin:
                String(
                    window.location.origin ||
                    ''
                ),
            settings:
                cloneObject(
                    settings
                ),
            sharedLibrary:
                cloneObject(
                    loadSharedLibrary()
                ),
            businessScripts: {},
            businessAdapterStatus:
                listBusinessBackupAdapters(),
            skippedBusinessScripts: []
        };
    }

    async function createSuiteBackupPayload(
        reason,
        options
    ) {
        const payload =
            createManagerBackupPayload(
                reason
            );

        const business =
            await collectBusinessBackupComponents(
                reason,
                options
            );

        payload.backupScope =
            'manager-and-registered-business-scripts';

        payload.businessScripts =
            business.components;

        payload.skippedBusinessScripts =
            business.skipped;

        payload.businessAdapterStatus =
            listBusinessBackupAdapters();

        return payload;
    }

    function isRecognizableManagerSettings(
        value
    ) {
        if (
            !value ||
            typeof value !== 'object' ||
            Array.isArray(value)
        ) {
            return false;
        }

        return [
            'theme',
            'customStyle',
            'openhis',
            'visible',
            'interfaceEnhancements',
            'scopeRules',
            'managerSectionCollapsed',
            'crossTabSyncEnabled'
        ].some(
            function (key) {
                return Object.prototype
                    .hasOwnProperty.call(
                        value,
                        key
                    );
            }
        );
    }

    function normalizeManagerBackupPayload(
        value
    ) {
        if (
            !value ||
            typeof value !== 'object' ||
            Array.isArray(value)
        ) {
            throw new Error(
                '备份文件不是有效的JSON对象。'
            );
        }

        const wrapped =
            value.schema ===
                SETTINGS_BACKUP_SCHEMA ||
            Object.prototype
                .hasOwnProperty.call(
                    value,
                    'settings'
                );

        const rawSettings =
            wrapped
                ? value.settings
                : value;

        if (
            !isRecognizableManagerSettings(
                rawSettings
            )
        ) {
            throw new Error(
                '文件中没有可识别的悬浮框管理器设置。'
            );
        }

        let importedSharedLibrary =
            null;

        if (
            wrapped &&
            value.sharedLibrary &&
            typeof value.sharedLibrary ===
                'object' &&
            !Array.isArray(
                value.sharedLibrary
            )
        ) {
            importedSharedLibrary =
                normalizeSharedLibrary(
                    value.sharedLibrary
                );
        }

        return {
            schema:
                SETTINGS_BACKUP_SCHEMA,
            schemaVersion:
                SETTINGS_BACKUP_SCHEMA_VERSION,
            scriptVersion:
                String(
                    value.scriptVersion ||
                    ''
                ),
            createdAt:
                String(
                    value.createdAt ||
                    ''
                ),
            reason:
                String(
                    value.reason ||
                    ''
                ),
            origin:
                String(
                    value.origin ||
                    ''
                ),
            settings:
                normalizeStoredSettings(
                    rawSettings
                ),
            sharedLibrary:
                importedSharedLibrary,
            businessScripts:
                normalizeBusinessBackupComponents(
                    value.businessScripts ||
                    (
                        value.components &&
                        value.components
                            .businessScripts
                    ) ||
                    {}
                ),
            businessAdapterStatus:
                Array.isArray(
                    value.businessAdapterStatus
                )
                    ? cloneObject(
                        value.businessAdapterStatus
                    )
                    : [],
            skippedBusinessScripts:
                Array.isArray(
                    value.skippedBusinessScripts
                )
                    ? cloneObject(
                        value.skippedBusinessScripts
                    )
                    : []
        };
    }

    function openAutomaticManagerBackupDb() {
        return new Promise(
            function (resolve, reject) {
                if (!window.indexedDB) {
                    reject(
                        new Error(
                            '当前浏览器不支持IndexedDB。'
                        )
                    );
                    return;
                }

                let request;

                try {
                    request =
                        window.indexedDB.open(
                            SETTINGS_BACKUP_IDB_NAME,
                            SETTINGS_BACKUP_IDB_VERSION
                        );
                } catch (error) {
                    reject(error);
                    return;
                }

                request.onupgradeneeded =
                    function () {
                        const db =
                            request.result;

                        if (
                            !db.objectStoreNames.contains(
                                SETTINGS_BACKUP_IDB_STORE
                            )
                        ) {
                            db.createObjectStore(
                                SETTINGS_BACKUP_IDB_STORE
                            );
                        }
                    };

                request.onsuccess =
                    function () {
                        resolve(
                            request.result
                        );
                    };

                request.onerror =
                    function () {
                        reject(
                            request.error ||
                            new Error(
                                '打开IndexedDB失败。'
                            )
                        );
                    };

                request.onblocked =
                    function () {
                        reject(
                            new Error(
                                'IndexedDB升级被其他页面阻塞，请关闭同源旧页面后重试。'
                            )
                        );
                    };
            }
        );
    }

    async function writeAutomaticManagerBackupToIndexedDb(
        payload
    ) {
        const db =
            await openAutomaticManagerBackupDb();

        try {
            await new Promise(
                function (resolve, reject) {
                    let transaction;

                    try {
                        transaction =
                            db.transaction(
                                SETTINGS_BACKUP_IDB_STORE,
                                'readwrite'
                            );

                        transaction.objectStore(
                            SETTINGS_BACKUP_IDB_STORE
                        ).put(
                            payload,
                            SETTINGS_BACKUP_IDB_RECORD_KEY
                        );
                    } catch (error) {
                        reject(error);
                        return;
                    }

                    transaction.oncomplete =
                        function () {
                            resolve();
                        };

                    transaction.onerror =
                        function () {
                            reject(
                                transaction.error ||
                                new Error(
                                    'IndexedDB写入回滚快照失败。'
                                )
                            );
                        };

                    transaction.onabort =
                        function () {
                            reject(
                                transaction.error ||
                                new Error(
                                    'IndexedDB写入回滚快照已中止。'
                                )
                            );
                        };
                }
            );
        } finally {
            try {
                db.close();
            } catch (error) {
                // 关闭失败不影响已完成的写入。
            }
        }
    }

    async function readAutomaticManagerBackupFromIndexedDb() {
        if (!window.indexedDB) {
            return null;
        }

        let db;

        try {
            db =
                await openAutomaticManagerBackupDb();

            const raw =
                await new Promise(
                    function (resolve, reject) {
                        let request;

                        try {
                            const transaction =
                                db.transaction(
                                    SETTINGS_BACKUP_IDB_STORE,
                                    'readonly'
                                );

                            request =
                                transaction.objectStore(
                                    SETTINGS_BACKUP_IDB_STORE
                                ).get(
                                    SETTINGS_BACKUP_IDB_RECORD_KEY
                                );
                        } catch (error) {
                            reject(error);
                            return;
                        }

                        request.onsuccess =
                            function () {
                                resolve(
                                    request.result ||
                                    null
                                );
                            };

                        request.onerror =
                            function () {
                                reject(
                                    request.error ||
                                    new Error(
                                        'IndexedDB读取回滚快照失败。'
                                    )
                                );
                            };
                    }
                );

            if (!raw) {
                return null;
            }

            return normalizeManagerBackupPayload(
                raw
            );
        } catch (error) {
            return null;
        } finally {
            if (db) {
                try {
                    db.close();
                } catch (error) {
                    // 关闭失败不影响读取。
                }
            }
        }
    }

    function loadLegacyAutomaticManagerBackup() {
        if (
            automaticManagerBackupLegacyChecked
        ) {
            return null;
        }

        automaticManagerBackupLegacyChecked =
            true;

        try {
            const raw =
                localStorage.getItem(
                    SETTINGS_BACKUP_STORAGE_KEY
                );

            if (!raw) {
                return null;
            }

            const backup =
                normalizeManagerBackupPayload(
                    JSON.parse(
                        raw
                    )
                );

            automaticManagerBackupCache =
                backup;

            /*
             * 旧localStorage快照自动后台迁移到IndexedDB。
             * 只有迁移写入成功后才删除旧键，失败则保留原数据。
             */
            writeAutomaticManagerBackupToIndexedDb(
                backup
            ).then(
                function () {
                    try {
                        localStorage.removeItem(
                            SETTINGS_BACKUP_STORAGE_KEY
                        );
                    } catch (error) {
                        // 删除旧键失败不影响新快照。
                    }
                }
            ).catch(
                function () {
                    // 迁移失败时继续保留旧localStorage快照。
                }
            );

            return backup;
        } catch (error) {
            return null;
        }
    }

    async function saveAutomaticManagerBackup(
        reason
    ) {
        const payload =
            createManagerBackupPayload(
                reason ||
                'before-import'
            );

        automaticManagerBackupCache =
            payload;

        try {
            await writeAutomaticManagerBackupToIndexedDb(
                payload
            );

            /*
             * 新后端写入成功后删除旧localStorage大快照，
             * 释放OHA/WebView2同源localStorage配额。
             */
            try {
                localStorage.removeItem(
                    SETTINGS_BACKUP_STORAGE_KEY
                );
            } catch (error) {
                // 清理失败不影响IndexedDB快照可用性。
            }

            automaticManagerBackupLegacyChecked =
                true;

            return payload;
        } catch (indexedDbError) {
            /*
             * 极旧浏览器／禁用IndexedDB环境继续兼容原localStorage。
             * 若localStorage也已满，则抛出明确错误并阻止后续覆盖，
             * 保证“没有可持久回滚快照就不执行还原”。
             */
            try {
                localStorage.setItem(
                    SETTINGS_BACKUP_STORAGE_KEY,
                    JSON.stringify(
                        payload
                    )
                );

                automaticManagerBackupLegacyChecked =
                    true;

                return payload;
            } catch (localStorageError) {
                automaticManagerBackupCache =
                    null;

                throw new Error(
                    '无法保存还原前本地快照：IndexedDB写入失败（' +
                    String(
                        indexedDbError &&
                        indexedDbError.message ||
                        indexedDbError
                    ) +
                    '）；localStorage兜底亦失败（' +
                    String(
                        localStorageError &&
                        localStorageError.message ||
                        localStorageError
                    ) +
                    '）。为避免无法撤销，本次导入／WebDAV还原已中止。'
                );
            }
        }
    }

    function loadAutomaticManagerBackup() {
        if (automaticManagerBackupCache) {
            return automaticManagerBackupCache;
        }

        return loadLegacyAutomaticManagerBackup();
    }

    async function loadAutomaticManagerBackupAsync() {
        const immediate =
            loadAutomaticManagerBackup();

        if (immediate) {
            return immediate;
        }

        const indexedBackup =
            await readAutomaticManagerBackupFromIndexedDb();

        if (indexedBackup) {
            automaticManagerBackupCache =
                indexedBackup;
        }

        return indexedBackup;
    }

    function hydrateAutomaticManagerBackupCache() {
        if (
            automaticManagerBackupHydrationPromise
        ) {
            return automaticManagerBackupHydrationPromise;
        }

        automaticManagerBackupHydrationPromise =
            loadAutomaticManagerBackupAsync()
                .catch(
                    function () {
                        return null;
                    }
                )
                .finally(
                    function () {
                        automaticManagerBackupHydrationPromise =
                            null;
                    }
                );

        return automaticManagerBackupHydrationPromise;
    }

    function managerBackupFileName() {
        const date =
            new Date();

        function pad(value) {
            return String(value)
                .padStart(
                    2,
                    '0'
                );
        }

        const stamp =
            date.getFullYear() +
            pad(date.getMonth() + 1) +
            pad(date.getDate()) +
            '_' +
            pad(date.getHours()) +
            pad(date.getMinutes()) +
            pad(date.getSeconds());

        return (
            '智慧医疗_悬浮框管理器与业务脚本备份_' +
            stamp +
            '.json'
        );
    }

    function webdavBackupFileName() {
        const date =
            new Date();

        function pad(
            value,
            length
        ) {
            return String(value)
                .padStart(
                    length || 2,
                    '0'
                );
        }

        const stamp =
            date.getFullYear() +
            pad(date.getMonth() + 1) +
            pad(date.getDate()) +
            '_' +
            pad(date.getHours()) +
            pad(date.getMinutes()) +
            pad(date.getSeconds()) +
            '_' +
            pad(
                date.getMilliseconds(),
                3
            );

        return (
            '智慧医疗_悬浮框管理器与业务脚本云端备份_' +
            stamp +
            '.json'
        );
    }

    function webdavAutomaticBackupFileName(
        config
    ) {
        const clientId =
            String(
                config &&
                config.clientId ||
                'default'
            )
                .replace(
                    /[^a-zA-Z0-9_-]/g,
                    ''
                ) ||
            'default';

        return (
            '智慧医疗_设置与业务脚本自动同步_' +
            clientId +
            '.json'
        );
    }

    async function uploadSuiteBackupToWebdav(
        rawConfig,
        reason,
        options
    ) {
        const source =
            options &&
            typeof options === 'object'
                ? options
                : {};

        const config =
            assertWebdavConfig(
                rawConfig
            );

        const directoryUrl =
            await ensureWebdavDirectory(
                config
            );

        const payload =
            await createSuiteBackupPayload(
                reason ||
                'manual-webdav-upload',
                options
            );

        const fileName =
            String(
                source.remoteFileName ||
                webdavBackupFileName()
            );

        if (
            !fileName ||
            /[\\/]/.test(fileName) ||
            !/\.json$/i.test(fileName)
        ) {
            throw new Error(
                '云端备份文件名无效。'
            );
        }

        const fileUrl =
            webdavJoinUrl(
                directoryUrl,
                fileName,
                false
            );

        const content =
            JSON.stringify(
                payload,
                null,
                2
            );

        const uploadHeaders = {
            'Content-Type':
                'application/json;charset=utf-8'
        };

        if (
            source.allowOverwrite !==
                true
        ) {
            uploadHeaders[
                'If-None-Match'
            ] = '*';
        }

        const response =
            await webdavRequest(
                'PUT',
                fileUrl,
                config,
                {
                    headers:
                        uploadHeaders,
                    body: content,
                    timeout: 30000
                }
            );

        if (
            !webdavResponseSucceeded(
                response
            )
        ) {
            throw webdavReadableError(
                response,
                '上传云端备份'
            );
        }

        return {
            fileName: fileName,
            fileUrl: fileUrl,
            bytes:
                new TextEncoder()
                    .encode(content)
                    .length,
            payload: payload
        };
    }


    async function uploadScriptSourcesToWebdav(
        rawConfig,
        reason
    ) {
        const config =
            assertWebdavConfig(
                rawConfig
            );

        const sourceDirectoryConfig =
            Object.assign(
                {},
                config,
                {
                    remoteDirectory:
                        [
                            config.remoteDirectory,
                            'script-sources'
                        ]
                            .filter(Boolean)
                            .join('/')
                }
            );

        const directoryUrl =
            await ensureWebdavDirectory(
                sourceDirectoryConfig
            );

        const collected =
            await collectScriptSourceBackupComponents(
                reason ||
                'manual-source-backup'
            );

        if (!collected.sources.length) {
            throw new Error(
                '当前没有已注册且可导出的脚本源码。'
            );
        }

        const uploaded = [];
        let totalBytes = 0;

        for (
            let index = 0;
            index < collected.sources.length;
            index += 1
        ) {
            const item =
                collected.sources[index];

            const fileUrl =
                webdavJoinUrl(
                    directoryUrl,
                    item.fileName,
                    false
                );

            const response =
                await webdavRequest(
                    'PUT',
                    fileUrl,
                    config,
                    {
                        headers: {
                            'Content-Type':
                                'application/javascript;charset=utf-8'
                        },
                        body:
                            item.source,
                        timeout:
                            60000
                    }
                );

            if (
                !webdavResponseSucceeded(
                    response
                )
            ) {
                throw webdavReadableError(
                    response,
                    '上传脚本源码“' +
                    item.name +
                    '”'
                );
            }

            uploaded.push({
                id: item.id,
                name: item.name,
                version: item.version,
                role: item.role,
                fileName: item.fileName,
                bytes: item.bytes
            });

            totalBytes +=
                item.bytes;
        }

        const manifest = {
            schema:
                'medical-userscript-source-backup-manifest',
            schemaVersion: 1,
            createdAt:
                new Date().toISOString(),
            reason:
                String(
                    reason ||
                    'manual-source-backup'
                ),
            origin:
                String(
                    location.origin ||
                    ''
                ),
            providerSignature:
                scriptSourceProviderSignature(),
            scripts:
                uploaded,
            skipped:
                collected.skipped
        };

        const manifestFileName =
            '智慧医疗_脚本源码备份清单.json';

        const manifestUrl =
            webdavJoinUrl(
                directoryUrl,
                manifestFileName,
                false
            );

        const manifestText =
            JSON.stringify(
                manifest,
                null,
                2
            );

        const manifestResponse =
            await webdavRequest(
                'PUT',
                manifestUrl,
                config,
                {
                    headers: {
                        'Content-Type':
                            'application/json;charset=utf-8'
                    },
                    body:
                        manifestText,
                    timeout:
                        30000
                }
            );

        if (
            !webdavResponseSucceeded(
                manifestResponse
            )
        ) {
            throw webdavReadableError(
                manifestResponse,
                '上传脚本源码备份清单'
            );
        }

        totalBytes +=
            new TextEncoder()
                .encode(
                    manifestText
                )
                .length;

        return {
            directoryUrl:
                directoryUrl,
            manifestUrl:
                manifestUrl,
            manifest:
                manifest,
            uploaded:
                uploaded,
            skipped:
                collected.skipped,
            bytes:
                totalBytes
        };
    }

    async function downloadWebdavBackupText(
        rawConfig,
        file
    ) {
        const config =
            assertWebdavConfig(
                rawConfig
            );

        const fileUrl =
            assertWebdavBackupFile(
                config,
                file
            );

        const response =
            await webdavRequest(
                'GET',
                fileUrl,
                config,
                {
                    timeout: 30000
                }
            );

        if (
            !webdavResponseSucceeded(
                response
            )
        ) {
            throw webdavReadableError(
                response,
                '下载云端备份'
            );
        }

        return String(
            response.text || ''
        );
    }

    async function deleteWebdavBackup(
        rawConfig,
        file
    ) {
        const config =
            assertWebdavConfig(
                rawConfig
            );

        const fileUrl =
            assertWebdavBackupFile(
                config,
                file
            );

        const response =
            await webdavRequest(
                'DELETE',
                fileUrl,
                config
            );

        if (
            !webdavResponseSucceeded(
                response
            ) &&
            response.status !== 404
        ) {
            throw webdavReadableError(
                response,
                '删除云端备份'
            );
        }

        return true;
    }

    function resolveTcmMappedName(
        value
    ) {
        const original =
            plainKnowledgeText(value)
                .replace(/^[★☆*]+\s*/, '');

        if (
            !original ||
            !sharedLibrary
                .settings
                .enableTcmNameMapping
        ) {
            return original;
        }

        const key =
            normalizeKnowledgeText(
                original
            );

        const matched =
            sharedLibrary
                .tcmMappings
                .find(function (item) {
                    if (
                        !item ||
                        item.enabled === false
                    ) {
                        return false;
                    }

                    return [
                        item.from,
                        item.to
                    ]
                        .concat(
                            item.aliases || []
                        )
                        .some(function (name) {
                            return (
                                normalizeKnowledgeText(
                                    name
                                ) === key
                            );
                        });
                });

        return matched
            ? matched.to
            : original;
    }

    function resolveDiagnosisMappedName(
        value
    ) {
        const original =
            plainKnowledgeText(value);

        if (
            !original ||
            !sharedLibrary
                .settings
                .enableDiagnosisNameMapping
        ) {
            return original;
        }

        const key =
            normalizeKnowledgeText(
                original
            );

        const matched =
            sharedLibrary
                .diagnosisMappings
                .find(function (item) {
                    if (
                        !item ||
                        item.enabled === false
                    ) {
                        return false;
                    }

                    return [
                        item.from,
                        item.to
                    ]
                        .concat(
                            item.aliases || []
                        )
                        .some(function (name) {
                            return (
                                normalizeKnowledgeText(
                                    name
                                ) === key
                            );
                        });
                });

        return matched
            ? matched.to
            : original;
    }

    function westernDrugSuggestions(
        query,
        limit
    ) {
        if (
            !sharedLibrary
                .settings
                .enableWesternDrugSuggestion
        ) {
            return [];
        }

        const target =
            normalizeKnowledgeText(
                query
            );

        const maximum =
            Math.max(
                1,
                Math.min(
                    100,
                    Number(limit) ||
                    20
                )
            );

        const scored = [];

        sharedLibrary
            .westernDrugs
            .forEach(function (item) {
                if (
                    !item ||
                    item.enabled === false
                ) {
                    return;
                }

                const values = [
                    item.name,
                    item.searchName,
                    item.code,
                    item.specification,
                    item.manufacturer
                ].concat(
                    item.aliases || []
                );

                const pinyinEnabled =
                    Boolean(
                        sharedLibrary
                            .settings
                            .enableWesternDrugPinyinInitials
                    );

                const pinyinValues =
                    pinyinEnabled
                        ? [
                            item.name,
                            item.searchName
                        ]
                            .concat(
                                item.aliases || []
                            )
                            .map(
                                westernDrugPinyinInitials
                            )
                            .filter(Boolean)
                        : [];

                let score =
                    target
                        ? -1
                        : 1;

                values.forEach(function (value) {
                    const normalized =
                        normalizeKnowledgeText(
                            value
                        );

                    if (!normalized) {
                        return;
                    }

                    if (normalized === target) {
                        score =
                            Math.max(
                                score,
                                1000
                            );
                    }
                    else if (
                        target &&
                        normalized.startsWith(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                700 -
                                normalized.length
                            );
                    }
                    else if (
                        target &&
                        normalized.includes(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                400 -
                                normalized.length
                            );
                    }
                });

                pinyinValues.forEach(function (value) {
                    const normalized =
                        normalizeKnowledgeText(
                            value
                        );

                    if (!normalized || !target) {
                        return;
                    }

                    if (normalized === target) {
                        score =
                            Math.max(
                                score,
                                900
                            );
                    }
                    else if (
                        normalized.startsWith(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                620 -
                                normalized.length
                            );
                    }
                    else if (
                        normalized.includes(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                320 -
                                normalized.length
                            );
                    }
                });

                if (score >= 0) {
                    const resultItem =
                        cloneObject(item);

                    if (pinyinEnabled) {
                        resultItem.pinyinInitials =
                            westernDrugPinyinInitials(
                                item.name ||
                                item.searchName
                            );
                    }

                    scored.push({
                        item: resultItem,
                        score: score
                    });
                }
            });

        return scored
            .sort(function (first, second) {
                return (
                    second.score -
                    first.score ||
                    String(
                        first.item.name
                    ).localeCompare(
                        String(
                            second.item.name
                        ),
                        'zh-CN'
                    )
                );
            })
            .slice(0, maximum)
            .map(function (entry) {
                return cloneObject(
                    entry.item
                );
            });
    }


    function chargeItemSuggestions(
        query,
        limit
    ) {
        if (
            !sharedLibrary
                .settings
                .enableChargeItemSuggestion
        ) {
            return [];
        }

        const target =
            normalizeKnowledgeText(
                query
            );

        const maximum =
            Math.max(
                1,
                Math.min(
                    100,
                    Number(limit) ||
                    20
                )
            );

        const pinyinEnabled =
            Boolean(
                sharedLibrary
                    .settings
                    .enableChargeItemPinyinInitials
            );

        const scored = [];

        sharedLibrary
            .chargeItems
            .forEach(function (item) {
                if (
                    !item ||
                    item.enabled === false
                ) {
                    return;
                }

                const normalizedName =
                    normalizeKnowledgeText(
                        item.name
                    );

                let score =
                    target
                        ? -1
                        : 1;

                if (
                    normalizedName &&
                    target
                ) {
                    if (
                        normalizedName ===
                        target
                    ) {
                        score = 1000;
                    }
                    else if (
                        normalizedName.startsWith(
                            target
                        )
                    ) {
                        score =
                            700 -
                            normalizedName.length;
                    }
                    else if (
                        normalizedName.includes(
                            target
                        )
                    ) {
                        score =
                            400 -
                            normalizedName.length;
                    }
                }

                if (
                    pinyinEnabled &&
                    target
                ) {
                    const initials =
                        normalizeKnowledgeText(
                            westernDrugPinyinInitials(
                                item.name
                            )
                        );

                    if (
                        initials === target
                    ) {
                        score =
                            Math.max(
                                score,
                                900
                            );
                    }
                    else if (
                        initials.startsWith(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                620 -
                                initials.length
                            );
                    }
                    else if (
                        initials.includes(
                            target
                        )
                    ) {
                        score =
                            Math.max(
                                score,
                                320 -
                                initials.length
                            );
                    }
                }

                if (score >= 0) {
                    const resultItem =
                        cloneObject(item);

                    if (pinyinEnabled) {
                        resultItem.pinyinInitials =
                            westernDrugPinyinInitials(
                                item.name
                            );
                    }

                    scored.push({
                        item: resultItem,
                        score: score
                    });
                }
            });

        return scored
            .sort(function (first, second) {
                return (
                    second.score -
                    first.score ||
                    String(
                        first.item.name
                    ).localeCompare(
                        String(
                            second.item.name
                        ),
                        'zh-CN'
                    )
                );
            })
            .slice(0, maximum)
            .map(function (entry) {
                return cloneObject(
                    entry.item
                );
            });
    }


    function publishSharedLibraryApi() {
        const api = {
            version: 4,
            storageKey:
                SHARED_LIBRARY_STORAGE_KEY,
            changedEvent:
                SHARED_LIBRARY_EVENT_NAME,
            getSnapshot:
                function () {
                    sharedLibrary =
                        loadSharedLibrary();

                    return cloneObject(
                        sharedLibrary
                    );
                },
            resolveTcmName:
                function (value) {
                    sharedLibrary =
                        loadSharedLibrary();

                    return resolveTcmMappedName(
                        value
                    );
                },
            resolveDiagnosisName:
                function (value) {
                    sharedLibrary =
                        loadSharedLibrary();

                    return resolveDiagnosisMappedName(
                        value
                    );
                },
            getDiagnosisMappings:
                function () {
                    sharedLibrary =
                        loadSharedLibrary();

                    return cloneObject(
                        sharedLibrary
                            .diagnosisMappings
                            .filter(function (item) {
                                return item.enabled !== false;
                            })
                    );
                },
            suggestWesternDrugs:
                function (query, limit) {
                    sharedLibrary =
                        loadSharedLibrary();

                    return westernDrugSuggestions(
                        query,
                        limit
                    );
                },
            suggestChargeItems:
                function (query, limit) {
                    sharedLibrary =
                        loadSharedLibrary();

                    return chargeItemSuggestions(
                        query,
                        limit
                    );
                }
        };

        try {
            Object.defineProperty(
                window,
                SHARED_LIBRARY_API_NAME,
                {
                    configurable: true,
                    enumerable: false,
                    writable: false,
                    value: api
                }
            );
        }
        catch (error) {
            window[
                SHARED_LIBRARY_API_NAME
            ] = api;
        }
    }

    function parseDelimitedLine(
        line,
        delimiter
    ) {
        const result = [];
        let current = '';
        let quoted = false;

        for (
            let index = 0;
            index < line.length;
            index += 1
        ) {
            const character =
                line[index];

            if (character === '"') {
                if (
                    quoted &&
                    line[index + 1] === '"'
                ) {
                    current += '"';
                    index += 1;
                }
                else {
                    quoted = !quoted;
                }

                continue;
            }

            if (
                character === delimiter &&
                !quoted
            ) {
                result.push(
                    plainKnowledgeText(
                        current
                    )
                );

                current = '';
                continue;
            }

            current += character;
        }

        result.push(
            plainKnowledgeText(
                current
            )
        );

        return result;
    }

    function parseDelimitedTable(
        text
    ) {
        const lines =
            String(text || '')
                .replace(/^\uFEFF/, '')
                .replace(/\r/g, '')
                .split('\n')
                .filter(function (line) {
                    return line.trim();
                });

        if (!lines.length) {
            return [];
        }

        const delimiter =
            lines[0].includes('\t')
                ? '\t'
                : ',';

        return lines.map(function (line) {
            return parseDelimitedLine(
                line,
                delimiter
            );
        });
    }

    function headerIndex(
        headers,
        names
    ) {
        const targets =
            names.map(
                normalizeKnowledgeText
            );

        return headers.findIndex(function (header) {
            const key =
                normalizeKnowledgeText(
                    header
                );

            return targets.some(function (target) {
                return (
                    key === target ||
                    key.includes(target) ||
                    target.includes(key)
                );
            });
        });
    }

    function westernDrugRowsFromDelimited(
        text
    ) {
        const rows =
            parseDelimitedTable(
                text
            );

        if (!rows.length) {
            return [];
        }

        const headers =
            rows[0];

        const indexes = {
            name:
                headerIndex(
                    headers,
                    [
                        '名称',
                        '药品名称',
                        '通用名',
                        '药品通用名'
                    ]
                ),
            searchName:
                headerIndex(
                    headers,
                    [
                        '检索名',
                        '检索名称',
                        '简拼',
                        '拼音',
                        '助记码'
                    ]
                ),
            specification:
                headerIndex(
                    headers,
                    ['规格']
                ),
            unit:
                headerIndex(
                    headers,
                    ['单位']
                ),
            manufacturer:
                headerIndex(
                    headers,
                    [
                        '生产厂家',
                        '厂家',
                        '生产企业'
                    ]
                ),
            code:
                headerIndex(
                    headers,
                    [
                        '药品编码',
                        '编码',
                        '代码',
                        '国家医保代码'
                    ]
                ),
            aliases:
                headerIndex(
                    headers,
                    [
                        '别名',
                        '其他名称'
                    ]
                ),
            note:
                headerIndex(
                    headers,
                    ['备注']
                )
        };

        const hasHeader =
            Object.keys(indexes)
                .some(function (key) {
                    return indexes[key] >= 0;
                });

        const dataRows =
            hasHeader
                ? rows.slice(1)
                : rows;

        return dataRows
            .map(function (row) {
                const valueAt =
                    function (index, fallbackIndex) {
                        const resolved =
                            index >= 0
                                ? index
                                : fallbackIndex;

                        return plainKnowledgeText(
                            row[resolved] ||
                            ''
                        );
                    };

                return normalizeWesternDrugEntry({
                    name:
                        valueAt(
                            indexes.name,
                            0
                        ),
                    searchName:
                        valueAt(
                            indexes.searchName,
                            1
                        ),
                    specification:
                        valueAt(
                            indexes.specification,
                            2
                        ),
                    unit:
                        valueAt(
                            indexes.unit,
                            3
                        ),
                    manufacturer:
                        valueAt(
                            indexes.manufacturer,
                            4
                        ),
                    code:
                        valueAt(
                            indexes.code,
                            5
                        ),
                    aliases:
                        valueAt(
                            indexes.aliases,
                            6
                        ),
                    note:
                        valueAt(
                            indexes.note,
                            7
                        )
                });
            })
            .filter(Boolean);
    }


    function chargeItemRowsFromDelimited(
        text
    ) {
        const rows =
            parseDelimitedTable(
                text
            );

        if (!rows.length) {
            return [];
        }

        const headerRowIndex =
            rows
                .slice(
                    0,
                    5
                )
                .findIndex(function (row) {
                    return row.some(
                        function (cell) {
                            const key =
                                normalizeKnowledgeText(
                                    cell
                                );

                            return (
                                key.includes(
                                    normalizeKnowledgeText(
                                        '收费项目名称'
                                    )
                                ) ||
                                key ===
                                    normalizeKnowledgeText(
                                        '项目名称'
                                    )
                            );
                        }
                    );
                });

        const headers =
            rows[
                headerRowIndex >= 0
                    ? headerRowIndex
                    : 0
            ];

        const indexes = {
            name:
                headerIndex(
                    headers,
                    [
                        '收费项目名称',
                        '项目名称',
                        '名称'
                    ]
                ),
            unit:
                headerIndex(
                    headers,
                    [
                        '计价单位',
                        '单位'
                    ]
                ),
            price:
                headerIndex(
                    headers,
                    [
                        '单价',
                        '价格'
                    ]
                )
        };

        const hasHeader =
            Object.keys(indexes)
                .some(function (key) {
                    return indexes[key] >= 0;
                });

        const dataRows =
            hasHeader
                ? rows.slice(
                    (
                        headerRowIndex >= 0
                            ? headerRowIndex
                            : 0
                    ) +
                    1
                )
                : rows;

        return dataRows
            .map(function (row) {
                const valueAt =
                    function (index, fallbackIndex) {
                        const resolved =
                            index >= 0
                                ? index
                                : fallbackIndex;

                        return plainKnowledgeText(
                            row[resolved] ||
                            ''
                        );
                    };

                return normalizeChargeItemEntry({
                    name:
                        valueAt(
                            indexes.name,
                            0
                        ),
                    unit:
                        valueAt(
                            indexes.unit,
                            1
                        ),
                    price:
                        valueAt(
                            indexes.price,
                            2
                        )
                });
            })
            .filter(Boolean);
    }

    function tcmMappingsFromEditorText(
        text
    ) {
        return String(text || '')
            .replace(/\r/g, '')
            .split('\n')
            .map(function (line) {
                const trimmed =
                    line.trim();

                if (
                    !trimmed ||
                    /^#/.test(trimmed)
                ) {
                    return null;
                }

                const parts =
                    trimmed.split(
                        /\s*(?:=>|＝|=|\t)\s*/
                    );

                if (parts.length < 2) {
                    return null;
                }

                return normalizeTcmMappingEntry({
                    from: parts[0],
                    to: parts[1],
                    aliases:
                        parts.slice(2)
                });
            })
            .filter(Boolean);
    }

