        if (cacheBackupFile) {
            cacheBackupFile.addEventListener('change', function () {
                const file = cacheBackupFile.files && cacheBackupFile.files[0];
                cacheBackupFile.value = '';
                if (!file) return;

                const reader = new FileReader();
                reader.onload = async function () {
                    try {
                        if (hasAnyBusinessTaskBusy()) {
                            throw new Error('读取文件期间检测到业务任务已经开始。');
                        }
                        const parsed = JSON.parse(String(reader.result || ''));
                        await cacheManagementRestorePackage(parsed);
                    } catch (error) {
                        setCacheManagementStatus(
                            '缓存还原失败：' +
                                String(error && error.message || error),
                            'error'
                        );
                        showSuiteStatus('患者缓存还原失败。', 'error');
                    }
                };
                reader.onerror = function () {
                    setCacheManagementStatus('缓存备份文件读取失败。', 'error');
                };
                reader.readAsText(file, 'utf-8');
            });
        }

