        function keepManagerInViewport() {
            const rect =
                managerPanel
                    .getBoundingClientRect();

            if (
                rect.width <= 0 ||
                rect.height <= 0
            ) {
                return;
            }

            const left =
                clampNumber(
                    rect.left,
                    4,
                    Math.max(
                        4,
                        window.innerWidth -
                        rect.width -
                        4
                    )
                );

            const top =
                clampNumber(
                    rect.top,
                    4,
                    Math.max(
                        4,
                        window.innerHeight -
                        rect.height -
                        4
                    )
                );

            host.style.left =
                Math.round(left) +
                'px';

            host.style.top =
                Math.round(top) +
                'px';

            host.style.right =
                'auto';

            host.style.bottom =
                'auto';
        }

        function saveManagerPosition() {
            const rect =
                managerPanel
                    .getBoundingClientRect();

            settings.managerPosition = {
                left:
                    Math.round(
                        rect.left
                    ),

                top:
                    Math.round(
                        rect.top
                    )
            };

            saveSettings();
        }

        function applyInitialManagerPosition() {
            const position =
                settings.managerPosition;

            if (
                position &&
                Number.isFinite(
                    Number(
                        position.left
                    )
                ) &&
                Number.isFinite(
                    Number(
                        position.top
                    )
                )
            ) {
                host.style.left =
                    Number(
                        position.left
                    ) +
                    'px';

                host.style.top =
                    Number(
                        position.top
                    ) +
                    'px';

                host.style.right =
                    'auto';

                host.style.bottom =
                    'auto';

                requestAnimationFrame(
                    keepManagerInViewport
                );
            }
        }

