        managerHeader.addEventListener(
            'pointerdown',
            function (event) {
                if (
                    event.target.closest(
                        '.manager-panel-toggle'
                    )
                ) {
                    return;
                }

                /*
                 * 绑定时，管理器标题栏与七个业务悬浮框使用同一套整体拖动逻辑。
                 * 管理器是排列中的第一个元素。
                 */
                if (
                    settings.bindPanels
                ) {
                    beginBoundPanelGroupDrag(
                        event,
                        managerHeader
                    );

                    return;
                }

                if (
                    event.pointerType ===
                        'mouse' &&
                    event.button !== 0
                ) {
                    return;
                }

                const startRect =
                    managerPanel
                        .getBoundingClientRect();

                const startX =
                    event.clientX;

                const startY =
                    event.clientY;

                const pointerId =
                    event.pointerId;

                managerHeader.style.cursor =
                    'grabbing';

                try {
                    managerHeader
                        .setPointerCapture(
                            pointerId
                        );
                } catch (error) {
                    // 浏览器不支持时使用document监听。
                }

                function onMove(
                    moveEvent
                ) {
                    if (
                        moveEvent.pointerId !==
                            pointerId
                    ) {
                        return;
                    }

                    const rect =
                        managerPanel
                            .getBoundingClientRect();

                    const left =
                        clampNumber(
                            startRect.left +
                                moveEvent.clientX -
                                startX,
                            4,
                            Math.max(
                                4,
                                window.innerWidth -
                                rect.width -
                                4
                            )
                        );

                    const top =
                        clampNumber(
                            startRect.top +
                                moveEvent.clientY -
                                startY,
                            4,
                            Math.max(
                                4,
                                window.innerHeight -
                                rect.height -
                                4
                            )
                        );

                    setPanelPosition(
                        host,
                        left,
                        top
                    );

                    moveEvent.preventDefault();
                }

                function finish(
                    finishEvent
                ) {
                    if (
                        finishEvent &&
                        finishEvent.pointerId !==
                            pointerId
                    ) {
                        return;
                    }

                    document.removeEventListener(
                        'pointermove',
                        onMove,
                        true
                    );

                    document.removeEventListener(
                        'pointerup',
                        finish,
                        true
                    );

                    document.removeEventListener(
                        'pointercancel',
                        finish,
                        true
                    );

                    managerHeader.style.cursor =
                        'move';

                    try {
                        managerHeader
                            .releasePointerCapture(
                                pointerId
                            );
                    } catch (error) {
                        // 未捕获时忽略。
                    }

                    saveManagerPosition();
                }

                document.addEventListener(
                    'pointermove',
                    onMove,
                    true
                );

                document.addEventListener(
                    'pointerup',
                    finish,
                    true
                );

                document.addEventListener(
                    'pointercancel',
                    finish,
                    true
                );

                event.preventDefault();
            }
        );


