        function managerSectionKeyFromTitle(titleText) {
            const title = String(titleText || '').trim();
            if (title === '风格管理') {
                return 'style';
            }
            if (title === '绑定与排列') {
                return 'layout';
            }
            if (title === '显示与隐藏') {
                return 'visibility';
            }
            if (title === '界面增强') {
                return 'interfaceEnhancement';
            }
            if (title === '全局AI调用管理') {
                return 'ai';
            }
            if (title === '医嘱预警联动') {
                return 'orderWarning';
            }
            if (title === '作用域网址管理（Tampermonkey @match）') {
                return 'scope';
            }
            if (title === 'OpenHIS患者及医嘱分页管理') {
                return 'openhis';
            }
            if (
                title ===
                '设置备份、多标签与WebDAV云端同步'
            ) {
                return 'backup';
            }
            if (title === '统一缓存管理') {
                return 'cache';
            }
            if (title === '隔离状态') {
                return 'isolation';
            }
            return '';
        }

        function initializeManagerSectionCollapsing() {
            const collapsedSettings =
                settings.managerSectionCollapsed || {};

            Array.from(
                root.querySelectorAll(
                    '.manager-body > .section'
                )
            ).forEach(function (section) {
                if (section === sharedSection) {
                    return;
                }

                const title =
                    section.querySelector(
                        ':scope > .section-title'
                    );

                if (!title) {
                    return;
                }

                const key =
                    managerSectionKeyFromTitle(
                        title.textContent
                    );

                if (!key) {
                    return;
                }

                section.dataset
                    .managerSectionKey =
                    key;

                const titleRow =
                    document.createElement(
                        'div'
                    );

                titleRow.className =
                    'section-title-row';

                section.insertBefore(
                    titleRow,
                    title
                );

                titleRow.appendChild(
                    title
                );

                const toggle =
                    document.createElement(
                        'button'
                    );

                toggle.type = 'button';
                toggle.className =
                    'section-collapse-button';

                titleRow.appendChild(
                    toggle
                );

                const content =
                    document.createElement(
                        'div'
                    );

                content.className =
                    'manager-section-content';

                Array.from(
                    section.childNodes
                ).forEach(function (node) {
                    if (node !== titleRow) {
                        content.appendChild(node);
                    }
                });

                section.appendChild(
                    content
                );

                function setCollapsed(
                    collapsed,
                    shouldSave
                ) {
                    const value =
                        Boolean(collapsed);

                    section.classList.toggle(
                        'collapsed',
                        value
                    );

                    toggle.textContent =
                        value
                            ? '展开'
                            : '折叠';

                    toggle.title =
                        value
                            ? '展开' + title.textContent
                            : '折叠' + title.textContent;

                    settings.managerSectionCollapsed =
                        Object.assign(
                            {},
                            settings.managerSectionCollapsed || {},
                            { [key]: value }
                        );

                    if (shouldSave !== false) {
                        saveSettings();
                    }
                }

                section
                    .__medicalSuiteSetCollapsed =
                    setCollapsed;

                toggle.addEventListener(
                    'click',
                    function () {
                        setCollapsed(
                            !section.classList.contains(
                                'collapsed'
                            ),
                            true
                        );
                    }
                );

                setCollapsed(
                    Boolean(
                        collapsedSettings[key]
                    ),
                    false
                );
            });
        }

