        function globalAiAdapterSecretCount(provider) {
            let count = 0;
            globalAiAdapters.forEach(function (adapter) {
                try {
                    if (adapter.hasApiKey(provider)) count += 1;
                } catch (error) {
                    // 单个适配器异常不影响其余统计。
                }
            });
            return count;
        }

        function refreshGlobalAiStatus(message) {
            if (!globalAiStatus) return;
            const total = globalAiAdapters.size;
            const deepseekCount = globalAiAdapterSecretCount('deepseek');
            const glmCount = globalAiAdapterSecretCount('glm');
            const openaiCount = globalAiAdapterSecretCount('openai');
            const config = normalizeGlobalAiSettings(settings.globalAi);
            const providerLabel = config.provider === 'glm'
                ? '智谱GLM'
                : config.provider === 'openai'
                    ? 'OpenAI'
                    : 'DeepSeek';
            const modeLabel = config.mode === 'direct'
                ? '强制直出'
                : config.mode === 'reasoning'
                    ? '强制推理'
                    : '跟随脚本';
            globalAiStatus.textContent =
                (message ? String(message) + '\n' : '') +
                '适配器：' + total + '/7；DeepSeek Key：' + deepseekCount + '/' + total +
                '；GLM Key：' + glmCount + '/' + total +
                '；OpenAI Key：' + openaiCount + '/' + total + '。\n' +
                '当前策略：' + (config.enabled ? '已启用' : '未启用') +
                '｜' + providerLabel + '｜' + modeLabel + '。';
        }

        function refreshGlobalAiControls(message) {
            const config = normalizeGlobalAiSettings(settings.globalAi);
            settings.globalAi = config;
            if (globalAiEnabledInput) globalAiEnabledInput.checked = config.enabled;
            if (globalAiProviderSelect) globalAiProviderSelect.value = config.provider;
            if (globalAiModeSelect) globalAiModeSelect.value = config.mode;
            if (globalAiDeepSeekDirectModelInput) {
                globalAiDeepSeekDirectModelInput.value = config.deepseekDirectModel;
            }
            if (globalAiDeepSeekReasoningModelInput) {
                globalAiDeepSeekReasoningModelInput.value = config.deepseekReasoningModel;
            }
            if (globalAiGlmDirectModelInput) {
                globalAiGlmDirectModelInput.value = config.glmDirectModel;
            }
            if (globalAiGlmReasoningModelInput) {
                globalAiGlmReasoningModelInput.value = config.glmReasoningModel;
            }
            if (globalAiGlmReasoningEffortSelect) {
                globalAiGlmReasoningEffortSelect.value = config.glmReasoningEffort;
            }
            if (globalAiOpenAiDirectModelInput) {
                globalAiOpenAiDirectModelInput.value = config.openaiDirectModel;
            }
            if (globalAiOpenAiReasoningModelInput) {
                globalAiOpenAiReasoningModelInput.value = config.openaiReasoningModel;
            }
            if (globalAiOpenAiReasoningEffortSelect) {
                globalAiOpenAiReasoningEffortSelect.value = config.openaiReasoningEffort;
            }
            refreshGlobalAiStatus(message);
        }

        function saveGlobalAiControls() {
            settings.globalAi = normalizeGlobalAiSettings({
                enabled: globalAiEnabledInput && globalAiEnabledInput.checked,
                provider: globalAiProviderSelect && globalAiProviderSelect.value,
                mode: globalAiModeSelect && globalAiModeSelect.value,
                deepseekDirectModel: globalAiDeepSeekDirectModelInput && globalAiDeepSeekDirectModelInput.value,
                deepseekReasoningModel: globalAiDeepSeekReasoningModelInput && globalAiDeepSeekReasoningModelInput.value,
                glmDirectModel: globalAiGlmDirectModelInput && globalAiGlmDirectModelInput.value,
                glmReasoningModel: globalAiGlmReasoningModelInput && globalAiGlmReasoningModelInput.value,
                glmReasoningEffort: globalAiGlmReasoningEffortSelect && globalAiGlmReasoningEffortSelect.value,
                openaiDirectModel: globalAiOpenAiDirectModelInput && globalAiOpenAiDirectModelInput.value,
                openaiReasoningModel: globalAiOpenAiReasoningModelInput && globalAiOpenAiReasoningModelInput.value,
                openaiReasoningEffort: globalAiOpenAiReasoningEffortSelect && globalAiOpenAiReasoningEffortSelect.value
            });
            saveSettings();
            syncGlobalAiConfigToSharedStorage(settings.globalAi);
            refreshGlobalAiControls('全局AI策略已更新。');
        }

        function syncGlobalAiSecret(provider, input) {
            const value = String(input && input.value || '').trim();
            if (!value) {
                const providerLabel = provider === 'glm' ? 'GLM' : provider === 'openai' ? 'OpenAI' : 'DeepSeek';
                refreshGlobalAiStatus('请输入' + providerLabel + ' API Key后再同步。');
                return;
            }
            globalAiSessionSecrets[provider] = value;
            let success = 0;
            const failed = [];
            globalAiAdapters.forEach(function (adapter, key) {
                try {
                    if (adapter.setApiKey(provider, value) !== false) {
                        success += 1;
                    } else {
                        failed.push(key);
                    }
                } catch (error) {
                    failed.push(key);
                }
            });
            if (input) input.value = '';
            refreshGlobalAiStatus(
                (provider === 'glm' ? 'GLM' : provider === 'openai' ? 'OpenAI' : 'DeepSeek') +
                ' API Key已同步到' + success + '个已接入脚本' +
                (failed.length ? '；失败：' + failed.join('、') : '。')
            );
        }

        function clearGlobalAiSecret(provider) {
            if (!window.confirm(
                '确定清除七业务脚本中已保存的' +
                (provider === 'glm' ? 'GLM' : provider === 'openai' ? 'OpenAI' : 'DeepSeek') +
                ' API Key吗？\n不会修改全局模型策略。'
            )) return;
            globalAiSessionSecrets[provider] = '';
            let success = 0;
            globalAiAdapters.forEach(function (adapter) {
                try {
                    if (adapter.clearApiKey(provider) !== false) success += 1;
                } catch (error) {
                    // 继续清理其余脚本。
                }
            });
            refreshGlobalAiStatus(
                '已向' + success + '个已接入脚本发送' +
                (provider === 'glm' ? 'GLM' : provider === 'openai' ? 'OpenAI' : 'DeepSeek') + ' Key清除指令。'
            );
        }

        [
            globalAiEnabledInput,
            globalAiProviderSelect,
            globalAiModeSelect,
            globalAiDeepSeekDirectModelInput,
            globalAiDeepSeekReasoningModelInput,
            globalAiGlmDirectModelInput,
            globalAiGlmReasoningModelInput,
            globalAiGlmReasoningEffortSelect,
            globalAiOpenAiDirectModelInput,
            globalAiOpenAiReasoningModelInput,
            globalAiOpenAiReasoningEffortSelect
        ].filter(Boolean).forEach(function (control) {
            control.addEventListener('change', saveGlobalAiControls);
        });

        if (globalAiSyncDeepSeekKeyButton) {
            globalAiSyncDeepSeekKeyButton.addEventListener('click', function () {
                syncGlobalAiSecret('deepseek', globalAiDeepSeekKeyInput);
            });
        }
        if (globalAiSyncGlmKeyButton) {
            globalAiSyncGlmKeyButton.addEventListener('click', function () {
                syncGlobalAiSecret('glm', globalAiGlmKeyInput);
            });
        }
        if (globalAiSyncOpenAiKeyButton) {
            globalAiSyncOpenAiKeyButton.addEventListener('click', function () {
                syncGlobalAiSecret('openai', globalAiOpenAiKeyInput);
            });
        }
        if (globalAiClearDeepSeekKeyButton) {
            globalAiClearDeepSeekKeyButton.addEventListener('click', function () {
                clearGlobalAiSecret('deepseek');
            });
        }
        if (globalAiClearGlmKeyButton) {
            globalAiClearGlmKeyButton.addEventListener('click', function () {
                clearGlobalAiSecret('glm');
            });
        }
        if (globalAiClearOpenAiKeyButton) {
            globalAiClearOpenAiKeyButton.addEventListener('click', function () {
                clearGlobalAiSecret('openai');
            });
        }
        document.addEventListener(
            GLOBAL_AI_ADAPTER_CHANGED_EVENT_NAME,
            function () {
                refreshGlobalAiStatus();
            }
        );
        refreshGlobalAiControls();

        function refreshOrderWarningLinkageControls() {
            if (!orderWarningLinkageInput) {
                return;
            }

            orderWarningLinkageInput.checked =
                Boolean(
                    getOrderWarningLinkageSettings()
                        .enabled
                );

            const toast =
                getOrderWarningToastSettings();

            if (orderWarningToastHerbInput) {
                orderWarningToastHerbInput.checked =
                    toast.herb !== false;
            }

            if (orderWarningToastDrugInput) {
                orderWarningToastDrugInput.checked =
                    toast.drug !== false;
            }

            if (orderWarningToastPathwayInput) {
                orderWarningToastPathwayInput.checked =
                    toast.pathway !== false;
            }

            if (orderWarningToastMergeInput) {
                orderWarningToastMergeInput.checked =
                    orderWarningMergeToastEnabled();
            }

            syncOrderWarningToastSettingsToSharedStorage(false);
        }

        function refreshOpenHisOrderLogView() {
            if (!openHisOrderLogBody || !openHisOrderLogStatus) {
                return;
            }

            const allLogs = readOpenHisLocalOrderLogs();
            const filteredLogs = filteredOpenHisLocalOrderLogs();
            const openhis = getOpenHisSettings();
            const maximumRendered = 200;
            const visibleLogs = filteredLogs.slice(0, maximumRendered);

            if (openHisOrderLogEnabledInput) {
                openHisOrderLogEnabledInput.checked =
                    openhis.orderLogEnabled !== false;
            }

            if (openHisOrderLogDateInput) {
                openHisOrderLogDateInput.value =
                    normalizeOpenHisOrderLogDateFilter(
                        openhis.orderLogDateFilter
                    );
            }

            if (openHisOrderLogHideRawInput) {
                openHisOrderLogHideRawInput.checked =
                    openhis.orderLogHideRawDetail === true;
            }

            if (openHisOrderLogExcludeRawExportInput) {
                openHisOrderLogExcludeRawExportInput.checked =
                    openhis.orderLogExcludeRawOnCopyExport === true;
            }

            if (openHisOrderLogPanel && openHisOrderLogCollapseButton) {
                const collapsed = openhis.orderLogCollapsed === true;
                openHisOrderLogPanel.classList.toggle('collapsed', collapsed);
                openHisOrderLogCollapseButton.textContent = collapsed
                    ? '展开'
                    : '折叠';
                openHisOrderLogCollapseButton.title = collapsed
                    ? '展开医嘱操作变动日志'
                    : '折叠医嘱操作变动日志';
            }

            function rebuildLogFilterSelect(select, placeholder, values, selectedValue) {
                if (!select) return;
                select.innerHTML = '';
                const first = document.createElement('option');
                first.value = '';
                first.textContent = placeholder;
                select.appendChild(first);
                values.forEach(function (item) {
                    const option = document.createElement('option');
                    option.value = item.value;
                    option.textContent = item.label;
                    select.appendChild(option);
                });
                select.value = String(selectedValue || '');
            }

            const patientMap = new Map();
            const operationSet = new Set();
            allLogs.forEach(function (entry) {
                const patientKey = openHisOrderLogPatientFilterKey(entry);
                if (patientKey && !patientMap.has(patientKey)) {
                    patientMap.set(patientKey, openHisOrderLogPatientLabel(entry));
                }
                const operation = String(entry && entry.operation || '').trim();
                if (operation) operationSet.add(operation);
            });

            rebuildLogFilterSelect(
                openHisOrderLogPatientFilterSelect,
                '全部患者',
                Array.from(patientMap.entries()).map(function (item) {
                    return { value: item[0], label: item[1] };
                }).sort(function (a, b) {
                    return a.label.localeCompare(b.label, 'zh-CN');
                }),
                openhis.orderLogPatientFilter
            );

            rebuildLogFilterSelect(
                openHisOrderLogOperationFilterSelect,
                '全部操作',
                Array.from(operationSet).sort(function (a, b) {
                    return a.localeCompare(b, 'zh-CN');
                }).map(function (value) {
                    return { value: value, label: value };
                }),
                openhis.orderLogOperationFilter
            );

            while (openHisOrderLogBody.firstChild) {
                openHisOrderLogBody.removeChild(
                    openHisOrderLogBody.firstChild
                );
            }

            visibleLogs.forEach(function (entry) {
                const tr = document.createElement('tr');
                tr.dataset.orderLogId = String(entry.id || '');

                [
                    formatOpenHisOrderLogTime(entry.time),
                    openHisOrderLogPatientLabel(entry),
                    entry.operation || '医嘱操作'
                ].forEach(function (value) {
                    const td = document.createElement('td');
                    td.textContent = String(value || '');
                    tr.appendChild(td);
                });

                const detailTd = document.createElement('td');
                detailTd.className = 'openhis-order-log-detail-cell';

                if (entry.aiSummary) {
                    const ai = document.createElement('div');
                    ai.className = 'openhis-order-log-ai-summary';
                    ai.textContent = 'AI整理：' + String(entry.aiSummary);
                    detailTd.appendChild(ai);
                }
                else {
                    const local = document.createElement('div');
                    local.className = 'openhis-order-log-local-summary';
                    local.textContent = localOpenHisOrderLogKeySummary(entry);
                    detailTd.appendChild(local);
                }

                const raw = document.createElement('div');
                raw.className = 'openhis-order-log-raw-detail';
                raw.textContent = String(
                    entry.detail || entry.actionLabel || '未提取到医嘱详情'
                );
                raw.style.display = openhis.orderLogHideRawDetail === true
                    ? 'none'
                    : '';
                detailTd.appendChild(raw);

                const aiButton = document.createElement('button');
                aiButton.type = 'button';
                aiButton.className = 'openhis-order-log-ai-button';
                aiButton.dataset.orderLogId = String(entry.id || '');
                aiButton.textContent = entry.aiSummary
                    ? '重新AI整理'
                    : 'AI整理';
                aiButton.title =
                    '调用药品AI辅助自动录入脚本中已配置的DeepSeek接口，提取本条日志的药名/项目、剂量、用法、频次、组号及变更动作。';
                detailTd.appendChild(aiButton);
                tr.appendChild(detailTd);

                const resultTd = document.createElement('td');
                resultTd.textContent = openHisOrderLogResultLabel(entry);
                resultTd.className = entry.success
                    ? 'order-log-success'
                    : 'order-log-failed';
                tr.appendChild(resultTd);

                openHisOrderLogBody.appendChild(tr);
            });

            const filterText = String(openhis.filterText || '').trim();
            const activeFilterGroup =
                getActiveOpenHisFilterGroup(
                    openhis
                );
            const filterDescription =
                openhis.filterEnabled && filterText
                    ? (
                        '；已沿用上方患者筛选组“' +
                        activeFilterGroup.name +
                        '”：' +
                        (openhis.filterMode === 'all'
                            ? '同时匹配全部关键词'
                            : '匹配任一关键词') +
                        '（' + filterText.replace(/\s+/g, ' ') + '）'
                    )
                    : '；当前未启用患者关键词筛选';
            const dateFilter = normalizeOpenHisOrderLogDateFilter(
                openhis.orderLogDateFilter
            );
            const dateDescription = dateFilter
                ? ('；日志日期=' + dateFilter)
                : '；日志日期=全部';
            const patientDescription = openhis.orderLogPatientFilter
                ? ('；患者=' + (patientMap.get(openhis.orderLogPatientFilter) || '已筛选'))
                : '；患者=全部';
            const operationDescription = openhis.orderLogOperationFilter
                ? ('；操作=' + openhis.orderLogOperationFilter)
                : '；操作=全部';
            const rawDescription = openhis.orderLogHideRawDetail === true
                ? '；原始详情=已隐藏'
                : '';
            const exportRawDescription = openhis.orderLogExcludeRawOnCopyExport === true
                ? '；复制/导出=不含原始详情'
                : '';

            openHisOrderLogStatus.textContent =
                '本机累计日志' + allLogs.length +
                '条，当前筛选结果' + filteredLogs.length +
                '条' +
                (filteredLogs.length > maximumRendered
                    ? '，表格仅显示最近' + maximumRendered + '条，复制/导出仍包含全部筛选结果'
                    : '') +
                filterDescription +
                dateDescription +
                patientDescription +
                operationDescription +
                rawDescription +
                exportRawDescription +
                '。';
        }

        async function organizeAllFilteredOpenHisOrderLogs(button) {
            const candidates = filteredOpenHisLocalOrderLogs().filter(function (entry) {
                return !String(entry && entry.aiSummary || '').trim();
            });

            if (!candidates.length) {
                showSuiteStatus(
                    '当前筛选结果中没有尚待AI整理的日志；已有AI摘要不会重复调用。',
                    'normal'
                );
                return;
            }

            const oldText = button ? button.textContent : '';
            if (button) button.disabled = true;

            let successCount = 0;
            let failedCount = 0;

            for (let index = 0; index < candidates.length; index += 1) {
                const entry = candidates[index];
                if (button) {
                    button.textContent = 'AI整理 ' + (index + 1) + '/' + candidates.length;
                }
                if (openHisOrderLogStatus) {
                    openHisOrderLogStatus.textContent =
                        '正在AI整理当前筛选日志：' + (index + 1) + '/' + candidates.length +
                        '；成功' + successCount + '，失败' + failedCount + '。';
                }

                try {
                    const summary = await requestOpenHisOrderLogAiSummary(entry);
                    if (!updateOpenHisLocalOrderLogAiSummary(entry.id, summary)) {
                        throw new Error('AI结果写入本地日志失败');
                    }
                    successCount += 1;
                }
                catch (error) {
                    failedCount += 1;
                }

                if (index < candidates.length - 1) {
                    await new Promise(function (resolve) {
                        setTimeout(resolve, 350);
                    });
                }
            }

            if (button) {
                button.disabled = false;
                button.textContent = oldText || '一键AI整理全部';
            }

            refreshOpenHisOrderLogView();
            showSuiteStatus(
                '一键AI整理完成：成功' + successCount + '条，失败' + failedCount +
                '条。仅处理了当前筛选结果中原先没有AI摘要的日志。',
                failedCount ? 'warning' : 'success'
            );
        }

        function initializeOpenHisOrderLogColumnResizing() {
            if (!openHisOrderLogTable ||
                openHisOrderLogTable.dataset.resizeBound === '1') {
                return;
            }

            openHisOrderLogTable.dataset.resizeBound = '1';
            const cols = Array.from(
                openHisOrderLogTable.querySelectorAll('colgroup col')
            );
            const headers = Array.from(
                openHisOrderLogTable.querySelectorAll('thead th')
            );
            const minimums = [92, 105, 70, 190, 82];
            const defaults = [118, 150, 88, 430, 105];
            const openhis = getOpenHisSettings();
            const saved = Array.isArray(openhis.orderLogColumnWidths)
                ? openhis.orderLogColumnWidths
                : defaults;

            function applyWidths(widths) {
                let total = 0;
                cols.forEach(function (col, index) {
                    const width = Math.max(
                        minimums[index] || 70,
                        Math.min(900, Number(widths[index]) || defaults[index])
                    );
                    col.style.width = width + 'px';
                    total += width;
                });
                openHisOrderLogTable.style.width = Math.max(
                    total,
                    565
                ) + 'px';
            }

            applyWidths(saved);

            headers.forEach(function (header, index) {
                const handle = document.createElement('span');
                handle.className = 'order-log-col-resizer';
                handle.title = '拖动调整该列宽度';
                header.appendChild(handle);

                handle.addEventListener('mousedown', function (event) {
                    event.preventDefault();
                    event.stopPropagation();

                    const startX = event.clientX;
                    const currentWidths = cols.map(function (col, colIndex) {
                        return Math.max(
                            minimums[colIndex] || 70,
                            parseFloat(col.style.width) || defaults[colIndex]
                        );
                    });
                    const startWidth = currentWidths[index];

                    function onMove(moveEvent) {
                        const next = currentWidths.slice();
                        next[index] = Math.max(
                            minimums[index] || 70,
                            Math.min(900, startWidth + moveEvent.clientX - startX)
                        );
                        applyWidths(next);
                    }

                    function onUp() {
                        window.removeEventListener('mousemove', onMove, true);
                        window.removeEventListener('mouseup', onUp, true);

                        const next = cols.map(function (col, colIndex) {
                            return Math.max(
                                minimums[colIndex] || 70,
                                Math.round(parseFloat(col.style.width) || defaults[colIndex])
                            );
                        });
                        const latest = getOpenHisSettings();
                        latest.orderLogColumnWidths = next;
                        saveSettings();
                    }

                    window.addEventListener('mousemove', onMove, true);
                    window.addEventListener('mouseup', onUp, true);
                });
            });
        }

        initializeOpenHisOrderLogColumnResizing();
        refreshScopeManagerView();

        if (openHisOrderLogBody) {
            openHisOrderLogBody.addEventListener('click', function (event) {
                const button = event.target && event.target.closest
                    ? event.target.closest('.openhis-order-log-ai-button')
                    : null;
                if (!button) return;

                const id = String(button.dataset.orderLogId || '');
                const entry = readOpenHisLocalOrderLogs().find(function (item) {
                    return item && String(item.id || '') === id;
                });

                if (!entry) {
                    showSuiteStatus('未找到对应日志记录。', 'warning');
                    return;
                }

                button.disabled = true;
                button.textContent = 'AI整理中…';
                showSuiteStatus(
                    '正在调用DeepSeek整理本条医嘱操作日志；仅发送操作类型和医嘱详情，不发送患者姓名/住院号。',
                    'normal'
                );

                requestOpenHisOrderLogAiSummary(entry)
                    .then(function (summary) {
                        if (!updateOpenHisLocalOrderLogAiSummary(id, summary)) {
                            throw new Error('AI结果已返回，但本地日志写入失败');
                        }
                        refreshOpenHisOrderLogView();
                        showSuiteStatus('本条日志AI智能整理完成。', 'success');
                    })
                    .catch(function (error) {
                        button.disabled = false;
                        button.textContent = entry.aiSummary
                            ? '重新AI整理'
                            : 'AI整理';
                        showSuiteStatus(
                            'AI整理失败：' + error.message,
                            'error'
                        );
                    });
            });
        }

        function refreshOpenHisFilterGroupTabs() {
            if (!openHisFilterGroupTabs) {
                return;
            }

            const openhis =
                getOpenHisSettings();

            const groups =
                getOpenHisFilterGroupEntries(
                    openhis
                );

            const activeGroup =
                getActiveOpenHisFilterGroup(
                    openhis
                );

            openHisFilterGroupTabs.innerHTML =
                '';

            groups.forEach(
                function (group) {
                    const button =
                        document.createElement(
                            'button'
                        );

                    const active =
                        group.id ===
                        activeGroup.id;

                    button.type =
                        'button';
                    button.className =
                        'openhis-filter-group-tab' +
                        (
                            active
                                ? ' active'
                                : ''
                        );
                    button.dataset.groupId =
                        group.id;
                    button.setAttribute(
                        'role',
                        'tab'
                    );
                    button.setAttribute(
                        'aria-selected',
                        active
                            ? 'true'
                            : 'false'
                    );
                    button.textContent =
                        group.name;

                    const termCount =
                        parseOpenHisFilterTerms(
                            group.text
                        ).length;

                    button.title =
                        group.name +
                        '：' +
                        termCount +
                        '个关键词；' +
                        (
                            group.mode === 'all'
                                ? '同时匹配全部'
                                : '匹配任一'
                        );

                    openHisFilterGroupTabs
                        .appendChild(button);
                }
            );

            if (openHisFilterGroupStatus) {
                const activeTermCount =
                    parseOpenHisFilterTerms(
                        activeGroup.text
                    ).length;

                openHisFilterGroupStatus.textContent =
                    '当前组：“' +
                    activeGroup.name +
                    '”（' +
                    activeTermCount +
                    '个关键词）；共' +
                    groups.length +
                    '组。点击标签可快速切换并应用。';
            }

            if (openHisFilterGroupAddButton) {
                openHisFilterGroupAddButton.disabled =
                    groups.length >=
                    OPENHIS_FILTER_GROUP_LIMIT;
            }

            if (openHisFilterGroupRenameButton) {
                openHisFilterGroupRenameButton.disabled =
                    !activeGroup;
            }

            if (openHisFilterGroupDeleteButton) {
                openHisFilterGroupDeleteButton.disabled =
                    groups.length <= 1;
            }
        }

        function refreshOpenHisControls() {
            const openhis =
                getOpenHisSettings();

            const activeGroup =
                getActiveOpenHisFilterGroup(
                    openhis
                );

            refreshOpenHisFilterGroupTabs();

            openHisShowAllInput.checked =
                Boolean(
                    openhis.showAllPatients
                );

            openHisPageSizeInput.value =
                String(
                    openhis.pageSize ||
                    999
                );

            openHisAdviceAllInput.checked =
                openhis.showAllAdvice !==
                    false;

            openHisAdviceMergeLabelInput.checked =
                openhis.showAdviceMergeLabel !==
                    false;

            openHisAdviceMergeLabelInput.disabled =
                !openHisAdviceAllInput.checked;

            openHisDrgFilterEnabledInput.checked =
                Boolean(
                    openhis.drgFilterEnabled
                );

            const drgDoctors =
                openHisDrgDoctorList();
            const selectedDrgDoctor =
                String(
                    openhis.drgSelectedDoctor ||
                    ''
                ).trim();

            openHisDrgDoctorFilterSelect.innerHTML =
                '<option value="">全部责任医师（' +
                drgDoctors.reduce(function (sum, item) {
                    return sum + Number(item.count || 0);
                }, 0) +
                '）</option>' +
                drgDoctors.map(function (item) {
                    const option = document.createElement('option');
                    option.value = item.name;
                    option.textContent =
                        item.name +
                        '（' +
                        item.count +
                        '）';
                    return option.outerHTML;
                }).join('');

            openHisDrgDoctorFilterSelect.value =
                drgDoctors.some(function (item) {
                    return item.name === selectedDrgDoctor;
                })
                    ? selectedDrgDoctor
                    : '';

            /* 同步成功后即可预选责任医师；是否真正生效由“启用DRG助手筛选”控制。 */
            openHisDrgDoctorFilterSelect.disabled =
                !drgDoctors.length;

            openHisFilterEnabledInput.checked =
                Boolean(
                    openhis.filterEnabled
                );

            openHisFilterModeSelect.value =
                activeGroup.mode === 'all'
                    ? 'all'
                    : 'any';

            openHisAutoApplyInput.checked =
                openhis.autoApplyFilter !==
                    false;

            if (
                openHisFilterEditor.value !==
                String(
                    activeGroup.text || ''
                )
            ) {
                openHisFilterEditor.value =
                    String(
                        activeGroup.text || ''
                    );
            }

            openHisFilterEditor.disabled =
                !openhis.filterEnabled;

            openHisFilterModeSelect.disabled =
                !openhis.filterEnabled;

            openHisAutoApplyInput.disabled =
                !openhis.filterEnabled;

            refreshOpenHisRuntimeStatus();
            refreshOpenHisOrderLogView();
        }

        let pendingCrossTabSettings =
            false;

        let pendingCrossTabSyncTimer =
            null;

        function hasAnyBusinessTaskBusy() {
            return CONFIGS.some(
                function (config) {
                    return isConfigBusy(
                        config
                    );
                }
            );
        }

        function formatBackupCreatedAt(
            value
        ) {
            if (!value) {
                return '';
            }

            try {
                const date =
                    new Date(value);

                if (
                    !Number.isFinite(
                        date.getTime()
                    )
                ) {
                    return String(value);
                }

                return date.toLocaleString(
                    'zh-CN',
                    {
                        hour12: false
                    }
                );
            } catch (error) {
                return String(value);
            }
        }

        function formatWebdavFileSize(
            value
        ) {
            const size =
                Math.max(
                    0,
                    Number(value) ||
                    0
                );

            if (size < 1024) {
                return size + ' B';
            }

            if (size < 1024 * 1024) {
                return (
                    size / 1024
                ).toFixed(1) +
                    ' KB';
            }

            return (
                size /
                (1024 * 1024)
            ).toFixed(2) +
                ' MB';
        }

        function collectWebdavConfigFromControls() {
            const existing =
                loadWebdavConfig();

            return normalizeWebdavConfig({
                endpoint:
                    webdavEndpointInput
                        .value,
                username:
                    webdavUsernameInput
                        .value,
                password:
                    webdavPasswordInput
                        .value,
                rememberPassword:
                    webdavRememberPasswordInput
                        .checked,
                remoteDirectory:
                    webdavDirectoryInput
                        .value,
                autoUpload:
                    webdavAutoUploadInput
                        .checked,
                sourceAutoUpload:
                    webdavSourceAutoUploadInput
                        ? webdavSourceAutoUploadInput.checked
                        : true,
                clientId:
                    existing.clientId
            });
        }

        function saveWebdavControls() {
            const config =
                assertWebdavConfig(
                    collectWebdavConfigFromControls()
                );

            const saved =
                saveWebdavConfig(
                    config
                );

            webdavEndpointInput.value =
                saved.endpoint;

            webdavDirectoryInput.value =
                saved.remoteDirectory;

            return saved;
        }

        function refreshWebdavAdapterStatus() {
            if (!webdavAdapterStatus) {
                return;
            }

            const adapters =
                listBusinessBackupAdapters();

            const connected =
                adapters.filter(
                    function (item) {
                        return item.registered;
                    }
                );

            const names =
                connected.map(
                    function (item) {
                        return (
                            item.name +
                            (
                                item.canRestore
                                    ? ''
                                    : '（仅导出）'
                            )
                        );
                    }
                );

            const transportVersion =
                webdavTransportBridgeVersion();

            const transportText =
                transportVersion
                    ? (
                        'WebDAV传输：跨域传输助手已连接（v' +
                        transportVersion +
                        '，异源请求无需服务器CORS）。'
                    )
                    : (
                        webdavGmRequester()
                            ? 'WebDAV传输：已检测到油猴跨域请求接口。'
                            : 'WebDAV传输：未检测到跨域传输助手；异源WebDAV请先安装助手并刷新HIS页面。'
                    );

            const sourceProviders =
                listScriptSourceBackupProviders();

            const sourceNames =
                sourceProviders.map(
                    function (item) {
                        return (
                            item.name +
                            (
                                item.version
                                    ? ' v' +
                                        item.version
                                    : ''
                            )
                        );
                    }
                );

            webdavAdapterStatus.textContent =
                transportText +
                '\n数据备份范围：悬浮框管理器＋共享映射／联想库；' +
                '七业务脚本已接入 ' +
                connected.length +
                '/7' +
                (
                    names.length
                        ? '（' +
                            names.join('、') +
                            '）'
                        : '。'
                ) +
                '\n源码备份：已注册 ' +
                sourceProviders.length +
                ' 个脚本' +
                (
                    sourceNames.length
                        ? '（' +
                            sourceNames.join('、') +
                            '）'
                        : '。'
                ) +
                '；源码仅留档，不执行自动安装或覆盖。';
        }

        function refreshWebdavControls() {
            const config =
                loadWebdavConfig();

            webdavEndpointInput.value =
                config.endpoint;

            webdavUsernameInput.value =
                config.username;

            webdavPasswordInput.value =
                config.password;

            webdavDirectoryInput.value =
                config.remoteDirectory;

            webdavRememberPasswordInput.checked =
                config.rememberPassword;

            webdavAutoUploadInput.checked =
                config.autoUpload;

            if (webdavSourceAutoUploadInput) {
                webdavSourceAutoUploadInput.checked =
                    config.sourceAutoUpload !== false;
            }

            refreshWebdavAdapterStatus();
        }

        function setWebdavStatus(
            message,
            type
        ) {
            if (!webdavStatus) {
                return;
            }

            webdavStatus.classList.remove(
                'pending',
                'success',
                'error'
            );

            if (
                type === 'pending' ||
                type === 'success' ||
                type === 'error'
            ) {
                webdavStatus.classList.add(
                    type
                );
            }

            webdavStatus.textContent =
                String(
                    message ||
                    '尚未连接WebDAV服务器。'
                );
        }

        function setWebdavUiBusy(
            busy
        ) {
            webdavUiBusy =
                Boolean(busy);

            if (webdavBackupPanel) {
                webdavBackupPanel
                    .classList.toggle(
                        'webdav-actions-busy',
                        webdavUiBusy
                    );
            }

            webdavActionButtons.forEach(
                function (button) {
                    button.disabled =
                        webdavUiBusy;
                }
            );

            webdavFileList.disabled =
                webdavUiBusy;
        }

        function renderWebdavRemoteFiles(
            files,
            preferredUrl
        ) {
            webdavRemoteFiles =
                Array.isArray(files)
                    ? files.slice()
                    : [];

            webdavFileList.innerHTML = '';

            if (!webdavRemoteFiles.length) {
                const emptyOption =
                    document.createElement(
                        'option'
                    );

                emptyOption.value = '';
                emptyOption.textContent =
                    '云端目录中尚无JSON备份';
                emptyOption.disabled = true;

                webdavFileList.appendChild(
                    emptyOption
                );
                return;
            }

            webdavRemoteFiles.forEach(
                function (file, index) {
                    const option =
                        document.createElement(
                            'option'
                        );

                    option.value =
                        String(index);

                    option.textContent =
                        (
                            file.modifiedAt
                                ? formatBackupCreatedAt(
                                    file.modifiedAt
                                ) +
                                    ' ｜ '
                                : ''
                        ) +
                        file.name +
                        ' ｜ ' +
                        formatWebdavFileSize(
                            file.size
                        );

                    if (
                        preferredUrl &&
                        file.url ===
                            preferredUrl
                    ) {
                        option.selected =
                            true;
                    }

                    webdavFileList.appendChild(
                        option
                    );
                }
            );

            if (
                webdavFileList.selectedIndex <
                0
            ) {
                webdavFileList.selectedIndex =
                    0;
            }
        }

        function selectedWebdavFile() {
            const index =
                Number(
                    webdavFileList.value
                );

            if (
                !Number.isInteger(index) ||
                index < 0 ||
                index >=
                    webdavRemoteFiles.length
            ) {
                return null;
            }

            return webdavRemoteFiles[index];
        }

        async function refreshWebdavRemoteList(
            config,
            preferredUrl
        ) {
            const files =
                await listWebdavBackups(
                    config
                );

            renderWebdavRemoteFiles(
                files,
                preferredUrl
            );

            return files;
        }

        function refreshBackupAndSyncControls(
            message,
            pending
        ) {
            if (crossTabSyncInput) {
                crossTabSyncInput.checked =
                    settings.crossTabSyncEnabled !==
                        false;
            }

            refreshWebdavAdapterStatus();

            const automaticBackup =
                loadAutomaticManagerBackup();

            if (settingsBackupRestoreButton) {
                settingsBackupRestoreButton.disabled =
                    !automaticBackup;
            }

            if (!settingsBackupStatus) {
                return;
            }

            settingsBackupStatus.classList.toggle(
                'pending',
                pending === true
            );

            if (message) {
                settingsBackupStatus.textContent =
                    message;
                return;
            }

            const syncText =
                settings.crossTabSyncEnabled !==
                    false
                    ? '多标签页软同步已开启。'
                    : '多标签页实时同步已关闭；字段级安全保存仍然生效。';

            const backupText =
                automaticBackup
                    ? (
                        ' 可恢复最近一次导入前设置（' +
                        formatBackupCreatedAt(
                            automaticBackup.createdAt
                        ) +
                        '）。'
                    )
                    : ' 当前没有可恢复的导入前备份。';

            settingsBackupStatus.textContent =
                syncText +
                backupText;
        }

        function applyCurrentManagerSettingsToUi(
            statusMessage
        ) {
            applySuiteStyle();
            applyAllVisibility();
            refreshControls();
            refreshOpenHisControls();
            publishInterfaceEnhancementSettings('manager-ui-apply');
            applyManagerSectionCollapsedSettings();
            setManagerCollapsed(
                Boolean(
                    settings.managerCollapsed
                ),
                false
            );
            applyInitialManagerPosition();

            if (settings.bindPanels) {
                if (
                    !restoreBoundPositions(
                        false
                    )
                ) {
                    arrangeVisiblePanels(
                        undefined,
                        false
                    );
                }
            } else {
                restoreIndependentPositions();
            }

            if (
                shouldBindCollapseButtons()
            ) {
                syncBusinessPanelsCollapsed(
                    Boolean(
                        settings.managerCollapsed
                    )
                );
            }

            syncOrderWarningToastSettingsToSharedStorage(
                false
            );

            if (
                getOpenHisSettings().filterEnabled ||
                getOpenHisSettings().showAllPatients
            ) {
                scheduleOpenHisApply(
                    40
                );
            } else {
                restoreAllOpenHisPatientCards();
            }

            scheduleReminderToastCloseRefresh(
                20
            );

            refreshBackupAndSyncControls(
                statusMessage ||
                '',
                false
            );
        }

        function schedulePendingCrossTabSync() {
            clearTimeout(
                pendingCrossTabSyncTimer
            );

            pendingCrossTabSyncTimer =
                setTimeout(
                    flushPendingCrossTabSync,
                    500
                );
        }

        function flushPendingCrossTabSync() {
            if (!pendingCrossTabSettings) {
                return;
            }

            if (hasAnyBusinessTaskBusy()) {
                refreshBackupAndSyncControls(
                    '已收到其他标签页的设置变更；检测到业务任务正在执行，将在任务结束后自动应用，不会重置任务。',
                    true
                );
                schedulePendingCrossTabSync();
                return;
            }

            const latest =
                loadSettings();

            const localEnabled =
                settings.crossTabSyncEnabled !==
                    false;

            const latestEnabled =
                latest.crossTabSyncEnabled !==
                    false;

            pendingCrossTabSettings =
                false;

            if (
                !localEnabled &&
                !latestEnabled
            ) {
                refreshBackupAndSyncControls();
                return;
            }

            const result =
                adoptExternalSettings(
                    latest
                );

            applyCurrentManagerSettingsToUi(
                result.localPatchCount
                    ? (
                        '已同步其他标签页设置，并保留本页' +
                        result.localPatchCount +
                        '项尚未保存的局部修改。'
                    )
                    : '已同步其他标签页的最新设置；当前页面及业务任务均未刷新。'
            );
        }

