        sharedWesternFile.addEventListener(
            'change',
            function () {
                const file =
                    sharedWesternFile.files &&
                    sharedWesternFile.files[0];

                sharedWesternFile.value = '';

                if (!file) {
                    return;
                }

                const lowerName =
                    String(file.name || '')
                        .toLowerCase();

                if (/\.xls[x]?$/.test(lowerName)) {
                    showSuiteStatus(
                        '当前脚本未内置二进制Excel解析器。请先在Excel中把药品目录另存为CSV，再导入。',
                        'error'
                    );
                    return;
                }

                const reader =
                    new FileReader();

                reader.onload =
                    function () {
                        try {
                            const content =
                                String(
                                    reader.result ||
                                    ''
                                );

                            let incoming = [];

                            if (/\.json$/.test(lowerName)) {
                                const parsed =
                                    JSON.parse(content);

                                const list =
                                    Array.isArray(parsed)
                                        ? parsed
                                        : parsed.westernDrugs;

                                if (!Array.isArray(list)) {
                                    throw new Error(
                                        'JSON中没有westernDrugs数组。'
                                    );
                                }

                                incoming =
                                    list
                                        .map(normalizeWesternDrugEntry)
                                        .filter(Boolean);
                            }
                            else {
                                incoming =
                                    westernDrugRowsFromDelimited(
                                        content
                                    );
                            }

                            if (!incoming.length) {
                                throw new Error(
                                    '未识别到有效药品记录。'
                                );
                            }

                            sharedLibrary.westernDrugs =
                                mergeWesternDrugLists(
                                    sharedLibrary
                                        .westernDrugs,
                                    incoming
                                );

                            saveSharedLibrary(
                                'import-western-drugs'
                            );

                            refreshSharedControls(true);

                            showSuiteStatus(
                                '药品目录导入完成：本次识别' +
                                incoming.length +
                                '条，合并后共' +
                                sharedLibrary
                                    .westernDrugs
                                    .length +
                                '条。',
                                'success'
                            );
                        }
                        catch (error) {
                            showSuiteStatus(
                                '西药联想库导入失败：' +
                                error.message,
                                'error'
                            );
                        }
                    };

                reader.readAsText(
                    file,
                    'utf-8'
                );
            }
        );

