        function applyManagerBackupPackage(
            backup,
            reason
        ) {
            settings =
                cloneObject(
                    backup.settings
                );

            const settingsResult =
                saveSettings({
                    replaceAll: true,
                    skipCloudSync: true
                });

            if (settingsResult.error) {
                throw settingsResult.error;
            }

            if (backup.sharedLibrary) {
                sharedLibrary =
                    normalizeSharedLibrary(
                        backup.sharedLibrary
                    );

                saveSharedLibrary(
                    reason ||
                    'settings-backup-import'
                );
            }

            pendingCrossTabSettings =
                false;

            clearTimeout(
                pendingCrossTabSyncTimer
            );

            applyCurrentManagerSettingsToUi(
                reason === 'settings-backup-restore'
                    ? '已恢复最近一次导入前的管理器设置与共享库；页面和业务任务均未刷新。'
                    : '设置备份导入成功；已软应用到当前标签页，页面和业务任务均未刷新。'
            );
        }

        async function applySuiteBackupPackage(
            backup,
            reason
        ) {
            cancelScheduledWebdavAutomaticBackup();

            applyManagerBackupPackage(
                backup,
                reason
            );

            const businessResult =
                await restoreBusinessBackupComponents(
                    backup,
                    reason
                );

            return businessResult;
        }

