        if (openHisOrderLogHandoffButton) {
            openHisOrderLogHandoffButton.addEventListener('click', function () {
                const logs = filteredOpenHisLocalOrderLogs();
                if (!logs.length) {
                    showSuiteStatus(
                        '当前筛选条件下没有可用于交班总结的本机医嘱操作日志。',
                        'warning'
                    );
                    return;
                }

                const button = openHisOrderLogHandoffButton;
                const oldText = button.textContent;
                button.disabled = true;
                button.textContent = '总结中…';
                showSuiteStatus(
                    '正在根据当前筛选日志生成医护交班格式；患者身份字段在本机用匿名代号替换后再发送给AI，返回后再本地恢复。',
                    'normal'
                );

                requestOpenHisOrderLogHandoff(logs)
                    .then(function (result) {
                        const openhis = getOpenHisSettings();
                        const dateFilter = normalizeOpenHisOrderLogDateFilter(
                            openhis.orderLogDateFilter
                        );
                        const header = [
                            '医嘱操作变动交班',
                            '日志范围：' + (dateFilter || '当前筛选全部日期') +
                                '；共' + result.count + '条本机操作日志',
                            '生成时间：' + formatOpenHisOrderLogTime(Date.now()),
                            ''
                        ].join('\n');
                        if (openHisOrderLogHandoffResult) {
                            openHisOrderLogHandoffResult.value =
                                header + result.text +
                                '\n\n说明：仅基于当前浏览器本机操作日志整理，不代表HIS服务器完整审计记录。';
                        }
                        if (openHisOrderLogHandoffPanel) {
                            openHisOrderLogHandoffPanel.style.display = '';
                        }
                        showSuiteStatus(
                            '医护交班格式总结已生成，共整理' + result.count + '条筛选日志。',
                            'success'
                        );
                    })
                    .catch(function (error) {
                        showSuiteStatus(
                            '总结日志失败：' + error.message,
                            'error'
                        );
                    })
                    .finally(function () {
                        button.disabled = false;
                        button.textContent = oldText || '总结日志';
                    });
            });
        }

