        if (openHisOrderLogCloudManageClearAllButton) {
            openHisOrderLogCloudManageClearAllButton.addEventListener(
                'click',
                async function () {
                    if (openHisOrderLogCloudBusy) return;

                    let config;
                    let files;
                    try {
                        config = saveWebdavControls();
                        files = await listOpenHisOrderLogCloudArchives(config);
                    } catch (error) {
                        setOpenHisOrderLogCloudManageStatus(
                            '读取失败：' + error.message,
                            'error'
                        );
                        showSuiteStatus(
                            '读取云端日志列表失败：' + error.message,
                            'error'
                        );
                        return;
                    }

                    if (!files.length) {
                        setOpenHisOrderLogCloudManageStatus(
                            '云端order-logs目录中没有可清空的医嘱日志归档。'
                        );
                        showSuiteStatus(
                            '云端order-logs目录中没有可清空的医嘱日志归档。',
                            'normal'
                        );
                        return;
                    }

                    if (!window.confirm(
                        '确定清空全部' + files.length +
                        '个设备的云端医嘱日志归档吗？\n\n只会删除order-logs中的医嘱日志文件；不会清空任何设备的本机日志，也不会删除普通WebDAV备份或源码快照。'
                    )) {
                        return;
                    }

                    if (!window.confirm(
                        '再次确认：云端历史日志一旦删除，超过各设备本机3000条上限的旧记录可能无法恢复。\n\n确定继续永久清空全部云端医嘱日志吗？'
                    )) {
                        return;
                    }

                    setOpenHisOrderLogCloudManageBusy(true);
                    setOpenHisOrderLogCloudManageStatus(
                        '正在清空全部云端医嘱日志，请勿关闭页面……'
                    );

                    try {
                        const result = await clearAllOpenHisOrderLogCloudArchives(
                            config
                        );
                        setOpenHisOrderLogCloudManageBusy(false);
                        const warning = result.skipped.length > 0;
                        setOpenHisOrderLogCloudManageStatus(
                            '清空完成：删除' + result.deleted.length +
                            '个归档' +
                            (warning
                                ? '；' + result.skipped.length + '个删除失败，已保留'
                                : '；未影响本机日志。'),
                            warning ? 'warning' : ''
                        );
                        showSuiteStatus(
                            warning
                                ? '云端日志已部分清空，但有文件删除失败，请查看管理列表。'
                                : '全部云端医嘱日志已清空；各设备本机日志未删除。',
                            warning ? 'warning' : 'success'
                        );
                        await refreshOpenHisOrderLogCloudManagePanel();
                    } catch (error) {
                        setOpenHisOrderLogCloudManageBusy(false);
                        setOpenHisOrderLogCloudManageStatus(
                            '清空失败：' + error.message,
                            'error'
                        );
                        showSuiteStatus(
                            '清空全部云端日志失败：' + error.message,
                            'error'
                        );
                    }
                }
            );
        }

